-- Sukhyang ERP Database Backup
-- Database: sukhyang
-- Date: 2026-06-16 18:19:44

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for `auth_logs`
-- ----------------------------
DROP TABLE IF EXISTS `auth_logs`;
CREATE TABLE `auth_logs` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `user_id` varchar(36) DEFAULT NULL COMMENT 'auth_users.id 참조',
  `username` varchar(50) DEFAULT NULL COMMENT '로그인 ID (삭제된 계정 포함)',
  `log_type` enum('auth','user','system') NOT NULL DEFAULT 'auth' COMMENT '로그 유형 (auth=인증, user=업무, system=시스템)',
  `action_type` varchar(50) NOT NULL COMMENT '행동 유형 (login, logout, password_change, approve, reject, etc.)',
  `action_detail` text DEFAULT NULL COMMENT '추가 설명 (예: IP, User-Agent, 이유 등)',
  `ip_address` varchar(45) DEFAULT NULL COMMENT '접속 IP',
  `user_agent` varchar(255) DEFAULT NULL COMMENT '브라우저/기기 정보',
  `success` tinyint(1) DEFAULT 1 COMMENT '성공 여부 (1=성공, 0=실패)',
  `ref_table` varchar(100) DEFAULT NULL COMMENT '관련 테이블명 (예: user_profiles, documents)',
  `ref_id` varchar(36) DEFAULT NULL COMMENT '관련 레코드 ID',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '기록 일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '행위자 (관리자 승인 등)',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_action_type` (`action_type`),
  KEY `idx_log_type` (`log_type`) USING BTREE,
  KEY `idx_created_at` (`created_at`) USING BTREE,
  CONSTRAINT `fk_auth_logs_user` FOREIGN KEY (`user_id`) REFERENCES `auth_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='사용자 인증 및 승인 로그 테이블';

-- Data for `auth_logs`

-- ----------------------------
-- Table structure for `auth_permissions`
-- ----------------------------
DROP TABLE IF EXISTS `auth_permissions`;
CREATE TABLE `auth_permissions` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL AUTO_INCREMENT COMMENT '순번 (AUTO_INCREMENT)',
  `permission_key` varchar(100) NOT NULL COMMENT '권한 키 (예: user.view, ledger.edit)',
  `permission_name` varchar(100) NOT NULL COMMENT '권한 이름 (한글 표시용)',
  `description` varchar(255) DEFAULT NULL COMMENT '권한 설명',
  `category` varchar(50) DEFAULT NULL COMMENT '카테고리',
  `page_key` varchar(100) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1 COMMENT '활성화 여부 (1=사용, 0=비활성)',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '등록 시각',
  `created_by` varchar(100) DEFAULT NULL COMMENT '등록자ID',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정 시각',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_permission_key` (`permission_key`) USING BTREE,
  UNIQUE KEY `uk_code` (`sort_no`) USING BTREE,
  KEY `idx_auth_permissions_page_key` (`page_key`)
) ENGINE=InnoDB AUTO_INCREMENT=1001011 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='시스템 기능별 접근권한 정의 테이블 (UUID + 순번 구조)';

-- Data for `auth_permissions`

-- ----------------------------
-- Table structure for `auth_role_permissions`
-- ----------------------------
DROP TABLE IF EXISTS `auth_role_permissions`;
CREATE TABLE `auth_role_permissions` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL AUTO_INCREMENT COMMENT '순번 (AUTO_INCREMENT)',
  `role_id` varchar(36) NOT NULL COMMENT '역할 ID (auth_roles.id 참조)',
  `permission_id` varchar(36) NOT NULL COMMENT '권한 ID (auth_permissions.id 참조)',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '등록 시각',
  `created_by` varchar(100) DEFAULT NULL COMMENT '등록자ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_role_permission` (`role_id`,`permission_id`) USING BTREE,
  UNIQUE KEY `uk_code` (`sort_no`) USING BTREE,
  KEY `idx_permission_id` (`permission_id`) USING BTREE,
  CONSTRAINT `fk_auth_role_permissions_permission` FOREIGN KEY (`permission_id`) REFERENCES `auth_permissions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_auth_role_permissions_role` FOREIGN KEY (`role_id`) REFERENCES `auth_roles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=513 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='역할별 권한 매핑 테이블 (UUID + 순번 구조)';

-- Data for `auth_role_permissions`

-- ----------------------------
-- Table structure for `auth_roles`
-- ----------------------------
DROP TABLE IF EXISTS `auth_roles`;
CREATE TABLE `auth_roles` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL AUTO_INCREMENT COMMENT '순번 (AUTO_INCREMENT)',
  `role_key` varchar(50) NOT NULL COMMENT '역할 키값 (예: admin, manager, staff)',
  `role_name` varchar(100) NOT NULL COMMENT '역할 이름 (예: 관리자, 부서장, 일반직원)',
  `description` varchar(255) DEFAULT NULL COMMENT '역할 설명',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '활성화 여부 (1=활성, 0=비활성)',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '생성일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자 ID (auth_users.id 참조)',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_bY` varchar(100) DEFAULT NULL COMMENT '수정자ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_role_key` (`role_key`),
  UNIQUE KEY `uk_code` (`sort_no`) USING BTREE,
  KEY `fk_auth_roles_created_by` (`created_by`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='시스템 역할(Role) 정의 테이블 (UUID + 순번 구조)';

-- Data for `auth_roles`

-- ----------------------------
-- Table structure for `auth_users`
-- ----------------------------
DROP TABLE IF EXISTS `auth_users`;
CREATE TABLE `auth_users` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `username` varchar(50) NOT NULL COMMENT '로그인 ID',
  `password` varchar(255) NOT NULL COMMENT '비밀번호 (해시)',
  `email` varchar(100) DEFAULT NULL COMMENT '이메일',
  `two_factor_enabled` tinyint(1) DEFAULT 0 COMMENT '2단계 인증 여부',
  `email_notify` tinyint(1) NOT NULL DEFAULT 1 COMMENT '이메일알림설정',
  `sms_notify` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'SMS알림설정',
  `approved` tinyint(1) DEFAULT 0 COMMENT '승인 여부 (관리자 승인)',
  `approved_at` datetime DEFAULT current_timestamp() COMMENT '승인 일시(관리자 승인)',
  `approved_by` varchar(100) DEFAULT NULL COMMENT '승인자 (관리자메일주소)',
  `role_id` varchar(36) DEFAULT NULL COMMENT '역할ID(user_roles.id FK)',
  `login_fail_count` int(11) unsigned zerofill DEFAULT 00000000000 COMMENT '로그인 실패 횟수',
  `account_locked_until` datetime DEFAULT NULL COMMENT '계정 잠금 만료일시',
  `last_login` datetime DEFAULT NULL COMMENT '마지막 로그인 일시',
  `last_login_ip` varchar(45) DEFAULT NULL COMMENT '마지막 로그인 IP',
  `last_login_device` varchar(512) DEFAULT NULL COMMENT '마지막 로그인 디바이스',
  `password_updated_at` datetime DEFAULT current_timestamp() COMMENT '비밀번호 변경일',
  `password_updated_by` varchar(100) DEFAULT NULL COMMENT '비밀번호 변경자ID',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '활성 계정 여부',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '가입일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자 ID',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자 ID',
  `deleted_at` datetime DEFAULT NULL COMMENT '비활성화일시 계정 관리용',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '비활성화자ID 계정 관리용',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  KEY `fk_auth_users_role` (`role_id`),
  CONSTRAINT `fk_auth_users_role` FOREIGN KEY (`role_id`) REFERENCES `auth_roles` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='사용자 로그인/인증 계정 테이블 (Auth Core)';

-- Data for `auth_users`

-- ----------------------------
-- Table structure for `dashboard_calendar_events`
-- ----------------------------
DROP TABLE IF EXISTS `dashboard_calendar_events`;
CREATE TABLE `dashboard_calendar_events` (
  `id` varchar(120) NOT NULL COMMENT '#CORE iCal UID (이벤트 고유 식별자)',
  `calendar_id` varchar(100) NOT NULL COMMENT '#CORE Synology Calendar ID',
  `owner_user_id` char(36) NOT NULL COMMENT 'ERP 사용자 ID (이 이벤트의 소유자, 멀티유저 데이터 격리용)',
  `synology_login_id` varchar(100) DEFAULT NULL COMMENT '이 이벤트가 동기화된 Synology 로그인 계정 ID (데이터 출처 계정 추적용)',
  `href` varchar(255) NOT NULL COMMENT '#CORE CalDAV 리소스 경로',
  `etag` varchar(255) DEFAULT NULL COMMENT '#CalDAV 객체 버전 식별자 (ETag, 수정/삭제 시 사용)',
  `type` varchar(20) DEFAULT NULL COMMENT '#RAW VEVENT / VTODO 등',
  `sequence` int(11) DEFAULT NULL COMMENT '#RAW iCal SEQUENCE',
  `dtstamp` varchar(30) DEFAULT NULL COMMENT '#RAW DTSTAMP (UTC iCal)',
  `created` varchar(30) DEFAULT NULL COMMENT '#RAW CREATED (iCal)',
  `last_modified` varchar(30) DEFAULT NULL COMMENT '#RAW LAST-MODIFIED (iCal)',
  `title` varchar(255) DEFAULT NULL COMMENT '#ERP 이벤트 제목 (SUMMARY)',
  `description` text DEFAULT NULL COMMENT '#ERP 설명',
  `location` varchar(255) DEFAULT NULL COMMENT '#ERP 위치',
  `event_color` varchar(20) DEFAULT NULL COMMENT '#ERP 이벤트 대표색 (SUMMARY bar)',
  `admin_event_color` varchar(20) DEFAULT NULL COMMENT '관리자 지정 이벤트 색상',
  `dtstart` varchar(50) DEFAULT NULL COMMENT '#ERP DTSTART 원문 (DATE or DATE-TIME)',
  `dtend` varchar(50) DEFAULT NULL COMMENT '#ERP DTEND 원문',
  `dtstart_ymd` char(8) DEFAULT NULL COMMENT '#SYS 파생컬럼: DTSTART YYYYMMDD (인덱스 최적화용)',
  `dtend_ymd` char(8) DEFAULT NULL COMMENT '#SYS 파생컬럼: DTEND YYYYMMDD (인덱스 최적화용)',
  `all_day` tinyint(1) NOT NULL DEFAULT 0 COMMENT '#ERP 종일 이벤트 여부',
  `status` varchar(20) DEFAULT NULL COMMENT '#ERP 상태',
  `priority` int(11) DEFAULT NULL COMMENT '#ERP 우선순위',
  `transp` varchar(20) DEFAULT NULL COMMENT '#RAW TRANSP (OPAQUE / TRANSPARENT)',
  `alarms_json` longtext DEFAULT NULL COMMENT '#RAW alarms[] 전체(JSON)',
  `attendees_json` longtext DEFAULT NULL COMMENT '#RAW attendees[] 전체(JSON)',
  `recurrence_json` longtext DEFAULT NULL COMMENT '#RAW rrule + rdate + exdate + exrule(JSON)',
  `categories_json` longtext DEFAULT NULL COMMENT '#RAW categories[] (JSON)',
  `comments_json` longtext DEFAULT NULL COMMENT '#RAW comment[] (JSON)',
  `attachments_json` longtext DEFAULT NULL COMMENT '#RAW ATTACH 정보(JSON)',
  `raw_json` longtext NOT NULL COMMENT '#RAW Synology EventObject 전체 원본 (1:1 보존)',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '#ERP 활성 여부',
  `synology_exists` tinyint(1) DEFAULT 1 COMMENT 'Synology 원본 존재 여부',
  `restored_at` datetime DEFAULT NULL COMMENT '휴지통 복원 보호용 타임스탬프',
  `deleted_at` datetime DEFAULT NULL COMMENT '#ERP 삭제 일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '#ERP 삭제자',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '#SYS DB 생성일',
  `created_by` varchar(100) DEFAULT NULL COMMENT '#SYS 생성자',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '#SYS DB 수정일',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '#SYS 수정자',
  UNIQUE KEY `uq_owner_calendar_uid` (`owner_user_id`,`calendar_id`,`id`) USING BTREE,
  UNIQUE KEY `uq_login_uid_calendar` (`synology_login_id`(50),`id`(100),`calendar_id`(50)) USING BTREE,
  KEY `idx_calendar` (`calendar_id`),
  KEY `idx_active` (`is_active`),
  KEY `idx_dtstart_ymd` (`dtstart_ymd`) COMMENT '기간조회 최적화: dtstart_ymd',
  KEY `idx_dtend_ymd` (`dtend_ymd`) COMMENT '기간조회 최적화: dtend_ymd',
  KEY `idx_calendar_period` (`calendar_id`,`dtstart_ymd`) COMMENT '기간조회 최적화: calendar_id + dtstart_ymd',
  KEY `idx_owner_user_id` (`owner_user_id`),
  KEY `idx_event_synology_login` (`synology_login_id`),
  KEY `idx_login_owner` (`synology_login_id`,`owner_user_id`),
  CONSTRAINT `fk_events_calendar` FOREIGN KEY (`calendar_id`) REFERENCES `dashboard_calendar_list` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Synology Calendar Event (RAW + ERP Shadow Columns)';

-- Data for `dashboard_calendar_events`

-- ----------------------------
-- Table structure for `dashboard_calendar_list`
-- ----------------------------
DROP TABLE IF EXISTS `dashboard_calendar_list`;
CREATE TABLE `dashboard_calendar_list` (
  `id` varchar(100) NOT NULL COMMENT 'Synology Calendar ID (cal_xxx)',
  `owner_user_id` varchar(50) DEFAULT NULL COMMENT 'ERP user_id (선택적 매핑)',
  `synology_login_id` varchar(100) DEFAULT NULL COMMENT '해당 캘린더가 동기화된 Synology 로그인 계정 ID (CalDAV 데이터 실제 소유자 식별용)',
  `synology_owner_principal` varchar(255) DEFAULT NULL COMMENT 'CalDAV owner principal URI (예: /principals/users/lee/)',
  `synology_login_principal` varchar(255) DEFAULT NULL COMMENT 'CalDAV current-user-principal URI (로그인 계정 principal)',
  `name` varchar(255) NOT NULL COMMENT 'Synology 캘린더 이름',
  `href` varchar(255) NOT NULL COMMENT 'Synology CalDAV Collection HREF',
  `type` enum('calendar','task') NOT NULL COMMENT 'Synology 캘린더 타입',
  `calendar_color` char(7) NOT NULL COMMENT 'Synology calendar color',
  `admin_calendar_color` char(7) DEFAULT NULL COMMENT 'ERP override calendar color',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'ERP 사용 여부',
  `is_personal` tinyint(1) NOT NULL DEFAULT 0 COMMENT '개인 캘린더 여부 (1=개인,0=공용)',
  `synced_at` datetime NOT NULL COMMENT 'Synology 기준 마지막 동기화 시각',
  `allowed_users_json` text DEFAULT NULL COMMENT '조회 권한 사용자 목록 (예: ["lee","song"])',
  `write_users_json` text DEFAULT NULL COMMENT '수정/삭제 권한 사용자 목록 (예: ["lee","song"])',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT 'SYS 생성일',
  `created_by` varchar(100) DEFAULT NULL COMMENT 'SYS 생성자',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'SYS 수정일',
  `updated_by` varchar(100) DEFAULT NULL COMMENT 'SYS 수정자',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_href` (`href`(191)),
  KEY `idx_active` (`is_active`),
  KEY `idx_calendar_personal` (`is_personal`),
  KEY `idx_owner_user_id` (`owner_user_id`) COMMENT '사용자 소유 캘린더 조회 최적화',
  KEY `idx_calendar_synology_login` (`synology_login_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Dashboard Calendar List (Synology raw + ERP admin color)';

-- Data for `dashboard_calendar_list`

-- ----------------------------
-- Table structure for `dashboard_calendar_sync_state`
-- ----------------------------
DROP TABLE IF EXISTS `dashboard_calendar_sync_state`;
CREATE TABLE `dashboard_calendar_sync_state` (
  `synology_login_id` varchar(100) NOT NULL,
  `is_running` tinyint(1) NOT NULL DEFAULT 0,
  `started_at` datetime DEFAULT NULL,
  `actor` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`synology_login_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

-- Data for `dashboard_calendar_sync_state`

-- ----------------------------
-- Table structure for `dashboard_calendar_tasks`
-- ----------------------------
DROP TABLE IF EXISTS `dashboard_calendar_tasks`;
CREATE TABLE `dashboard_calendar_tasks` (
  `id` varchar(120) NOT NULL COMMENT 'VTODO 고유 UID (CalDAV 기준 식별자)',
  `calendar_id` varchar(100) NOT NULL COMMENT 'Synology 캘린더 ID (cal_xxx)',
  `owner_user_id` varchar(50) NOT NULL DEFAULT '' COMMENT 'ERP 사용자 ID (이 태스크의 소유자, 멀티유저 데이터 격리용)',
  `synology_login_id` varchar(100) DEFAULT NULL COMMENT '이 태스크가 동기화된 Synology 로그인 계정 ID (CalDAV 데이터 소유 계정 식별용)',
  `href` varchar(255) NOT NULL COMMENT 'CalDAV 리소스 경로 (VTODO href)',
  `collection_href` varchar(255) DEFAULT NULL COMMENT 'CalDAV VTODO collection href (normalized, trailing slash included)',
  `etag` varchar(100) DEFAULT NULL COMMENT 'CalDAV 변경 감지용 ETag',
  `title` varchar(255) DEFAULT NULL COMMENT '태스크 제목 (SUMMARY)',
  `description` text DEFAULT NULL COMMENT '태스크 상세 설명 (DESCRIPTION)',
  `due` varchar(50) DEFAULT NULL COMMENT '마감일 (DUE, DATE 또는 DATE-TIME)',
  `due_ymd` varchar(50) DEFAULT NULL COMMENT '#SYS 파생컬럼: DUE YYYYMMDD',
  `status` varchar(20) DEFAULT NULL COMMENT '태스크 상태 (NEEDS-ACTION / COMPLETED)',
  `percent_complete` int(11) DEFAULT NULL COMMENT '진행률 (0~100, PERCENT-COMPLETE)',
  `completed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '태스크 완료 여부 (0: 미완료, 1: 완료)',
  `raw_json` longtext NOT NULL COMMENT 'Synology VTODO 원본 데이터 (JSON 전체 보관)',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'ERP 기준 활성 여부 (1: 사용, 0: 비활성/삭제됨)',
  `synology_exists` tinyint(1) DEFAULT 1 COMMENT 'Synology 원본 존재 여부',
  `restored_at` datetime DEFAULT NULL COMMENT '휴지통 복원 보호용 타임스탬프',
  `deleted_at` datetime DEFAULT NULL COMMENT 'ERP 삭제 처리 시각',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT 'ERP 삭제 처리자',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT 'DB 생성 일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT 'DB 생성자 (ERP 사용자 ID)',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'DB 최종 수정 일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT 'DB 최종 수정자 (ERP 사용자 ID)',
  UNIQUE KEY `uq_owner_uid_calendar` (`owner_user_id`,`id`,`calendar_id`) USING BTREE,
  UNIQUE KEY `uq_login_uid_calendar` (`synology_login_id`(50),`id`(100),`calendar_id`(50)) USING BTREE,
  KEY `idx_calendar` (`calendar_id`),
  KEY `idx_active` (`is_active`),
  KEY `idx_due_ymd` (`due_ymd`) COMMENT '기간조회 최적화',
  KEY `idx_calendar_start` (`calendar_id`) COMMENT '캘린더+시작일 복합조회 최적화',
  KEY `idx_owner_user_id` (`owner_user_id`),
  KEY `idx_task_synology_login` (`synology_login_id`),
  KEY `idx_login_owner` (`synology_login_id`,`owner_user_id`),
  CONSTRAINT `fk_tasks_calendar` FOREIGN KEY (`calendar_id`) REFERENCES `dashboard_calendar_list` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Data for `dashboard_calendar_tasks`

-- ----------------------------
-- Table structure for `dashboard_calendar_visibility`
-- ----------------------------
DROP TABLE IF EXISTS `dashboard_calendar_visibility`;
CREATE TABLE `dashboard_calendar_visibility` (
  `calendar_id` varchar(100) NOT NULL COMMENT 'FK → dashboard_calendar_list.id (컬렉션 실체 식별자)',
  `synology_login_id` varchar(100) NOT NULL COMMENT 'Synology 로그인 계정 ID (가시성 판단의 핵심 키)',
  `owner_user_id` varchar(50) NOT NULL DEFAULT '' COMMENT 'ERP 사용자 ID (로그인 계정과 ERP 사용자 매핑용)',
  `is_visible` tinyint(1) NOT NULL DEFAULT 1 COMMENT '해당 로그인 계정에서 캘린더 표시 여부 (1=표시,0=숨김)',
  `last_synced_at` datetime DEFAULT NULL COMMENT '이 로그인 계정 기준 마지막 동기화 시각',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT 'SYS 생성일',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'SYS 수정일',
  PRIMARY KEY (`calendar_id`,`synology_login_id`),
  KEY `idx_visibility_login` (`synology_login_id`),
  KEY `idx_visibility_owner` (`owner_user_id`),
  CONSTRAINT `fk_visibility_calendar` FOREIGN KEY (`calendar_id`) REFERENCES `dashboard_calendar_list` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Dashboard Calendar Visibility (Synology 로그인 계정 기준 가시성 제어 테이블)';

-- Data for `dashboard_calendar_visibility`

-- ----------------------------
-- Table structure for `ledger_accounts`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_accounts`;
CREATE TABLE `ledger_accounts` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL AUTO_INCREMENT COMMENT '순번 (AUTO_INCREMENT)',
  `account_code` varchar(20) NOT NULL COMMENT '계정코드 (예: 1000, 1100, 5101 등)',
  `account_name` varchar(100) NOT NULL COMMENT '계정과목명 (예: 현금, 보통예금, 노무비 등)',
  `parent_id` varchar(36) DEFAULT NULL,
  `account_group` enum('자산','부채','자본','수익','비용') NOT NULL COMMENT '계정 대분류 (재무제표 기준)',
  `normal_balance` enum('debit','credit') NOT NULL DEFAULT 'debit' COMMENT '정상잔액 (debit=차변, credit=대변)',
  `level` int(2) NOT NULL DEFAULT 1 COMMENT '계정 레벨 (자동계산)',
  `is_posting` tinyint(1) NOT NULL DEFAULT 1 COMMENT '전표 입력 가능 여부 (1=가능, 0=집계계정)',
  `note` varchar(255) DEFAULT NULL COMMENT '비고',
  `memo` text DEFAULT NULL COMMENT '관리자 메모',
  `allow_sub_account` tinyint(1) NOT NULL DEFAULT 0 COMMENT '보조계정 사용 여부 (1=사용, 0=미사용)',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '사용 여부 (1=사용, 0=비활성)',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '생성일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자 ID',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자 ID',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '삭제자 ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_account_code` (`account_code`) USING BTREE,
  KEY `idx_parent_id` (`parent_id`) USING BTREE,
  KEY `idx_account_group` (`account_group`) USING BTREE,
  KEY `idx_is_posting` (`is_posting`) USING BTREE,
  KEY `idx_is_active` (`is_active`) USING BTREE,
  KEY `idx_code` (`sort_no`) USING BTREE,
  CONSTRAINT `fk_account_parent` FOREIGN KEY (`parent_id`) REFERENCES `ledger_accounts` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=303 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='ERP 회계 계정과목 마스터 테이블 (계층구조 기반)';

-- Data for `ledger_accounts`

-- ----------------------------
-- Table structure for `ledger_bank_transactions`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_bank_transactions`;
CREATE TABLE `ledger_bank_transactions` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL DEFAULT 0 COMMENT '정렬 순번',
  `transaction_date` date NOT NULL COMMENT '거래일자',
  `transaction_datetime` datetime DEFAULT NULL COMMENT 'Transaction datetime',
  `transaction_time` time DEFAULT NULL COMMENT '거래시간',
  `bank_account_id` varchar(36) NOT NULL COMMENT '계좌 ID (BANK_ACCOUNT 보조원장)',
  `transaction_type` enum('DEPOSIT','WITHDRAW','TRANSFER','CARD_PAYMENT','INTEREST','FEE','ETC') NOT NULL DEFAULT 'ETC' COMMENT '입출금 유형',
  `deposit_amount` decimal(18,2) NOT NULL DEFAULT 0.00 COMMENT '입금 금액',
  `withdraw_amount` decimal(18,2) NOT NULL DEFAULT 0.00 COMMENT '출금 금액',
  `balance_amount` decimal(18,2) DEFAULT NULL COMMENT 'Actual bank balance after transaction',
  `balance_status` varchar(20) DEFAULT 'EMPTY' COMMENT 'ACTUAL, EMPTY, ESTIMATED, INVALID',
  `check_bill_amount` decimal(18,2) DEFAULT NULL COMMENT '수표어음금액',
  `currency_code` varchar(10) NOT NULL DEFAULT 'KRW' COMMENT '통화코드',
  `exchange_rate` decimal(18,6) NOT NULL DEFAULT 1.000000 COMMENT '환율',
  `description` varchar(500) DEFAULT NULL COMMENT '은행 적요',
  `counterparty_name` varchar(255) DEFAULT NULL COMMENT '상대방명',
  `counterparty_account_number` varchar(100) DEFAULT NULL COMMENT '상대방 계좌번호',
  `counterparty_bank_name` varchar(100) DEFAULT NULL COMMENT '상대방 은행명',
  `bank_reference_no` varchar(100) DEFAULT NULL COMMENT '은행 거래 고유번호',
  `evidence_id` varchar(36) DEFAULT NULL COMMENT '원본 증빙 ID',
  `status` enum('NORMAL','MATCHED','REVIEW','DELETED') NOT NULL DEFAULT 'NORMAL' COMMENT '처리 상태',
  `memo` text DEFAULT NULL COMMENT '메모',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성일시',
  `created_by` varchar(36) DEFAULT NULL COMMENT '생성자',
  `updated_at` datetime DEFAULT NULL COMMENT '수정일시',
  `updated_by` varchar(36) DEFAULT NULL COMMENT '수정자',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(36) DEFAULT NULL COMMENT '삭제자',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bank_reference_no` (`bank_account_id`,`bank_reference_no`),
  KEY `idx_transaction_date` (`transaction_date`),
  KEY `idx_bank_account_id` (`bank_account_id`),
  KEY `idx_status` (`status`),
  KEY `idx_evidence_id` (`evidence_id`),
  KEY `idx_ledger_bank_transactions_counterparty_account` (`counterparty_account_number`),
  KEY `idx_bank_evidence_deleted` (`evidence_id`,`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='은행 입출금 원장';

-- Data for `ledger_bank_transactions`

-- ----------------------------
-- Table structure for `ledger_client_account_patterns`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_client_account_patterns`;
CREATE TABLE `ledger_client_account_patterns` (
  `id` char(36) NOT NULL,
  `client_id` char(36) NOT NULL,
  `transaction_direction` varchar(30) NOT NULL,
  `line_type` varchar(10) NOT NULL,
  `account_id` char(36) NOT NULL,
  `usage_count` int(10) unsigned NOT NULL DEFAULT 0,
  `recent_score` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `last_used_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_lcap_client_direction_line_account` (`client_id`,`transaction_direction`,`line_type`,`account_id`),
  KEY `idx_lcap_client_rank` (`client_id`,`usage_count`,`last_used_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

