  `created_by` varchar(36) DEFAULT NULL COMMENT '생성자',
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(36) DEFAULT NULL COMMENT '수정자',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(36) DEFAULT NULL COMMENT '삭제자',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_evp_payload_evidence_ref` (`evidence_type`,`evidence_id`),
  KEY `idx_evp_payload_type_deleted` (`evidence_type`,`deleted_at`),
  KEY `idx_evp_payload_type_source_key` (`evidence_type`,`source_key`),
  KEY `idx_evp_payload_hash` (`payload_hash`),
  KEY `idx_evp_payload_latest_imported_at` (`latest_imported_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='증빙 payload 저장소';

