-- Table structure for `ledger_journal_learning_events`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_journal_learning_events`;
CREATE TABLE `ledger_journal_learning_events` (
  `id` char(36) NOT NULL,
  `transaction_id` char(36) NOT NULL,
  `voucher_id` char(36) NOT NULL,
  `voucher_line_id` char(36) DEFAULT NULL,
  `client_id` char(36) DEFAULT NULL,
  `project_id` char(36) DEFAULT NULL,
  `business_unit` varchar(30) DEFAULT NULL,
  `transaction_type` varchar(30) DEFAULT NULL,
  `transaction_direction` varchar(30) DEFAULT NULL,
  `import_type` varchar(30) DEFAULT NULL,
  `client_type` varchar(30) DEFAULT NULL,
  `line_no` int(11) NOT NULL DEFAULT 0,
  `line_type` varchar(10) NOT NULL,
  `recommended_line_type` varchar(10) DEFAULT NULL,
  `final_line_type` varchar(10) DEFAULT NULL,
  `recommended_account_id` char(36) DEFAULT NULL,
  `final_account_id` char(36) DEFAULT NULL,
  `recommended_amount` decimal(18,2) NOT NULL DEFAULT 0.00,
  `final_amount` decimal(18,2) NOT NULL DEFAULT 0.00,
  `recommend_source` varchar(30) DEFAULT NULL,
  `recommend_confidence` tinyint(3) unsigned DEFAULT NULL,
  `journal_rule_id` char(36) DEFAULT NULL,
  `recommend_reason` varchar(255) DEFAULT NULL,
  `is_user_modified` tinyint(1) NOT NULL DEFAULT 0,
  `failure_type` varchar(100) DEFAULT NULL,
  `source_payload` longtext DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `created_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ljle_transaction_id` (`transaction_id`),
  KEY `idx_ljle_voucher_id` (`voucher_id`),
  KEY `idx_ljle_client_context` (`client_id`,`transaction_direction`,`import_type`),
  KEY `idx_ljle_rule_id` (`journal_rule_id`),
  KEY `idx_ljle_modified` (`is_user_modified`,`failure_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for `ledger_journal_learning_events`

-- ----------------------------
-- Table structure for `ledger_journal_rules`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_journal_rules`;
CREATE TABLE `ledger_journal_rules` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '정렬/순서용 코드',
  `rule_code` varchar(50) NOT NULL COMMENT '분개규칙 코드 (예: PURCHASE_TAX, SALES_TAX)',
  `rule_name` varchar(100) NOT NULL COMMENT '분개규칙명',
  `business_unit` varchar(30) NOT NULL DEFAULT 'CONSTRUCTION' COMMENT '사업구분(BUSINESS_UNIT)',
  `transaction_type` varchar(30) NOT NULL DEFAULT 'GENERAL' COMMENT '거래유형(TRANSACTION_TYPE)',
  `import_type` varchar(50) NOT NULL COMMENT '자료유형 코드 (TAX_INVOICE, CARD_APPROVAL, BANK_TRANSACTION 등)',
  `transaction_direction` varchar(20) NOT NULL COMMENT '거래 방향 (PURCHASE=매입, SALES=매출, IN=입금, OUT=출금)',
  `client_type` varchar(30) DEFAULT NULL COMMENT '거래처구분(CLIENT_TYPE)',
  `debit_account_id` varchar(36) NOT NULL COMMENT '차변 계정 ID (ledger_accounts.id)',
  `credit_account_id` varchar(36) NOT NULL COMMENT '대변 계정 ID (ledger_accounts.id)',
  `vat_account_id` varchar(36) DEFAULT NULL COMMENT '부가세 계정 ID (부가세대급금/예수금 등)',
  `usage_count` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Confirmed usage count',
  `last_used_at` datetime DEFAULT NULL COMMENT 'Last confirmed usage time',
  `confidence_score` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT 'Rule confidence from confirmed usage',
  `description` text DEFAULT NULL COMMENT '분개규칙 설명',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '사용 여부 (1=사용, 0=중지)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자',
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '삭제자',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_rule_code` (`rule_code`) USING BTREE,
  KEY `idx_import_type` (`import_type`) USING BTREE,
  KEY `idx_transaction_direction` (`transaction_direction`) USING BTREE,
  KEY `idx_is_active` (`is_active`) USING BTREE,
  KEY `fk_journal_rules_debit_account` (`debit_account_id`) USING BTREE,
  KEY `fk_journal_rules_credit_account` (`credit_account_id`) USING BTREE,
  KEY `fk_journal_rules_vat_account` (`vat_account_id`) USING BTREE,
  KEY `idx_ledger_journal_rules_conditions` (`business_unit`,`transaction_type`,`transaction_direction`,`client_type`,`import_type`,`is_active`),
  CONSTRAINT `fk_journal_rules_credit_account` FOREIGN KEY (`credit_account_id`) REFERENCES `ledger_accounts` (`id`),
  CONSTRAINT `fk_journal_rules_debit_account` FOREIGN KEY (`debit_account_id`) REFERENCES `ledger_accounts` (`id`),
  CONSTRAINT `fk_journal_rules_vat_account` FOREIGN KEY (`vat_account_id`) REFERENCES `ledger_accounts` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='거래 기반 자동분개 규칙 테이블';

-- Data for `ledger_journal_rules`

-- ----------------------------
-- Table structure for `ledger_processing_item_actions`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_processing_item_actions`;
CREATE TABLE `ledger_processing_item_actions` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID(UUID)',
  `processing_item_id` varchar(36) NOT NULL COMMENT '처리 Item ID(ledger_processing_items.id)',
  `action_type` varchar(40) NOT NULL COMMENT '작업유형(CREATED,SPLIT,MERGE,CORRECTION,READY_CHANGE,STATUS_CHANGE,TRANSACTION_CREATED,VOUCHER_CREATED,LINKED,UNLINKED,REOPENED,REGENERATED,ROLLBACK,IGNORED,RESTORED 등)',
  `action_group_id` varchar(36) DEFAULT NULL COMMENT '동일 작업 묶음 ID(split/merge 등 복수 item 동시 처리 그룹)',
  `related_processing_item_id` varchar(36) DEFAULT NULL COMMENT '관련 처리 Item ID(split/merge/연결 상대 item)',
  `related_transaction_id` varchar(36) DEFAULT NULL COMMENT '관련 거래 ID(거래 생성/연결/재생성 시)',
  `related_voucher_id` varchar(36) DEFAULT NULL COMMENT '관련 전표 ID(전표 생성/연결/재생성 시)',
  `source_domain` varchar(30) DEFAULT NULL COMMENT '원천 도메인(EVIDENCE,BANK,CARD,ORDER,IMPORT 등)',
  `source_table` varchar(100) DEFAULT NULL COMMENT '원천 테이블명(내부 추적용)',
  `source_type` varchar(50) DEFAULT NULL COMMENT '원천 자료유형 또는 업무유형',
  `source_id` varchar(36) DEFAULT NULL COMMENT '원천 row ID',
  `before_status_json` longtext DEFAULT NULL COMMENT '작업 전 상태 JSON(item_status/readiness_status/correction_status/transaction_status/voucher_status 등)',
  `after_status_json` longtext DEFAULT NULL COMMENT '작업 후 상태 JSON(item_status/readiness_status/correction_status/transaction_status/voucher_status 등)',
  `before_payload_json` longtext DEFAULT NULL COMMENT '작업 전 업무 payload JSON(거래처/계정/금액/적요/보조계정 등)',
  `after_payload_json` longtext DEFAULT NULL COMMENT '작업 후 업무 payload JSON(사용자 보정 또는 시스템 처리 결과)',
  `action_reason` text DEFAULT NULL COMMENT '작업 사유 또는 사용자 입력 사유',
  `action_source` varchar(30) DEFAULT NULL COMMENT '작업 발생 경로(UI,API,IMPORT,AUTO_RULE,AI,BATCH 등)',
  `actor_type` varchar(30) NOT NULL DEFAULT 'USER' COMMENT '작업 주체 유형(USER,SYSTEM,AI,BATCH)',
  `actor_user_id` varchar(100) DEFAULT NULL COMMENT '작업 사용자 ID 또는 시스템 주체 ID',
  `error_message` text DEFAULT NULL COMMENT '실패/rollback/오류 사유',
  `metadata_json` longtext DEFAULT NULL COMMENT '확장 메타데이터 JSON',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '작업 발생일시',
  PRIMARY KEY (`id`),
  KEY `idx_processing_item_actions_item` (`processing_item_id`,`created_at`),
  KEY `idx_processing_item_actions_type` (`action_type`,`created_at`),
  KEY `idx_processing_item_actions_group` (`action_group_id`),
  KEY `idx_processing_item_actions_related_item` (`related_processing_item_id`),
  KEY `idx_processing_item_actions_transaction` (`related_transaction_id`),
  KEY `idx_processing_item_actions_voucher` (`related_voucher_id`),
  KEY `idx_processing_item_actions_source` (`source_domain`,`source_type`,`source_id`),
  KEY `idx_processing_item_actions_actor` (`actor_type`,`actor_user_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='생성센터 processing item workflow action history. 단순 audit log가 아니라 split/merge/보정/생성/rollback 업무 이력';

-- Data for `ledger_processing_item_actions`

-- ----------------------------
-- Table structure for `ledger_processing_items`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_processing_items`;
CREATE TABLE `ledger_processing_items` (
  `id` varchar(36) NOT NULL COMMENT '처리 Item 고유 ID(UUID). 생성센터 workflow tree node의 실제 참조 키',
  `source_table` varchar(100) NOT NULL COMMENT '원천 테이블명(내부 추적용). 업무 분기는 source_domain/source_type을 우선 사용',
  `source_id` varchar(36) NOT NULL COMMENT '원천 row ID. 증빙, 은행입출금 등 실제 원천 데이터의 PK',
  `source_type` varchar(30) NOT NULL COMMENT '원천 자료유형 또는 업무유형(TAX_INVOICE, BANK_TRANSACTION, CARD 등)',
  `source_domain` varchar(30) DEFAULT NULL COMMENT '원천 도메인(EVIDENCE, BANK, CARD, ORDER, IMPORT 등). 테이블명 직접 의존을 줄이기 위한 업무 분류',
  `parent_item_id` varchar(36) DEFAULT NULL COMMENT '상위 처리 Item ID. split/계층 tree에서 부모 node를 가리킴',
  `source_item_id` varchar(36) DEFAULT NULL COMMENT '이 Item이 파생된 직접 원본 Item ID. split/merge/재분리 출처 추적용',
  `lineage_root_id` varchar(36) DEFAULT NULL COMMENT '최초 lineage root Item ID. split/merge 반복 후에도 원래 업무 해석 뿌리를 추적',
  `display_path` varchar(80) DEFAULT NULL COMMENT '사용자에게 표시되는 workflow lineage 번호(예: 7-1-2). row 정렬 변경과 무관하게 item 계보 추적에 사용',
  `is_current` tinyint(1) NOT NULL DEFAULT 1 COMMENT '현재 생성센터 처리 대상 여부(1=current workflow item, 0=inactive lineage/history item)',
  `split_group_id` varchar(36) DEFAULT NULL COMMENT '동일 split 작업에 속한 processing item 그룹 ID. parent SPLIT 및 child CREATED action과 연결',
  `merge_group_id` varchar(36) DEFAULT NULL COMMENT '동일 merge 작업에 속한 processing item 그룹 ID. 병합 대상과 병합 결과를 묶는 workflow 그룹',
  `sort_no` int(11) NOT NULL DEFAULT 1 COMMENT '동일 parent/source 아래 표시 및 처리 순서. AUTO_INCREMENT 금지, workflow 정렬용 수동 순번',
  `item_type` varchar(30) NOT NULL DEFAULT 'DEFAULT' COMMENT '처리 Item 유형(DEFAULT, SPLIT, MERGE_RESULT, ADJUSTMENT 등). 회계 line 유형이 아닌 workflow node 유형',
  `line_type` varchar(30) DEFAULT NULL COMMENT '업무 라인 성격(상품, 수수료, 관세, 환차손 등). source 해석 결과를 표현',
  `item_status` varchar(30) NOT NULL DEFAULT 'ACTIVE' COMMENT '처리 Item 생명주기 상태(ACTIVE, SPLIT, MERGED, IGNORED, DELETED, ERROR 등)',
  `transaction_status` varchar(30) NOT NULL DEFAULT 'NONE' COMMENT '이 processing item 기준 거래 생성 상태(NONE, PARTIAL, PROCESSING, CREATED, ERROR 등)',
  `voucher_status` varchar(30) NOT NULL DEFAULT 'NONE' COMMENT '이 processing item 기준 전표 생성/전기 상태(NONE, PARTIAL, PROCESSING, CREATED, POSTED, ERROR 등)',
  `readiness_status` varchar(30) NOT NULL DEFAULT 'UNKNOWN' COMMENT '이 processing item의 생성 준비 상태(UNKNOWN, READY, NOT_READY, PARTIAL, BLOCKED 등)',
  `correction_status` varchar(30) NOT NULL DEFAULT 'NONE' COMMENT '이 processing item의 보정 상태(NONE, NEEDS_CORRECTION, CORRECTED, REJECTED 등)',
  `item_date` date DEFAULT NULL COMMENT '처리 Item 기준 업무일자. 거래/전표 생성 시 우선 참조되는 날짜',
  `client_id` varchar(36) DEFAULT NULL COMMENT '처리 Item에 매핑된 거래처 ID. 원천 row와 다르게 split 후 child별로 달라질 수 있음',
  `project_id` varchar(36) DEFAULT NULL COMMENT '처리 Item에 매핑된 프로젝트 ID. split/보정 후 item별 업무 귀속',
  `employee_id` varchar(36) DEFAULT NULL COMMENT '처리 Item에 매핑된 임직원 ID. 보정/정산/비용 귀속 추적용',
  `bank_account_id` varchar(36) DEFAULT NULL COMMENT '처리 Item에 연결된 은행계좌 ID. 은행 원천 또는 결제/수수료 item 처리용',
  `card_id` varchar(36) DEFAULT NULL COMMENT '처리 Item에 연결된 카드 ID. 카드 원천 또는 카드 비용 item 처리용',
  `account_id` varchar(36) DEFAULT NULL COMMENT '처리 Item에 추천/보정된 계정과목 ID. 최종 거래/전표 line 생성 전 업무 해석값',
  `quantity` decimal(18,3) DEFAULT NULL COMMENT '처리 Item 수량. split 전후 수량 합계 무결성 검증 대상',
  `unit_price` decimal(18,2) DEFAULT NULL COMMENT '처리 Item 단가. 원천 해석 또는 사용자 보정 결과',
  `supply_amount` decimal(18,2) DEFAULT NULL COMMENT '처리 Item 공급가액. split/merge 전후 금액 무결성 검증 대상',
  `vat_amount` decimal(18,2) DEFAULT NULL COMMENT '처리 Item 부가세액. split/merge 전후 금액 무결성 검증 대상',
  `total_amount` decimal(18,2) DEFAULT NULL COMMENT '처리 Item 합계금액. 거래/전표 생성 및 split/merge 무결성의 핵심 금액',
  `currency` varchar(10) DEFAULT 'KRW' COMMENT '처리 Item 통화. split/merge 시 동일 통화 검증 기준',
  `description` text DEFAULT NULL COMMENT '처리 Item 업무 설명/적요. 사용자 split/보정 후 거래/전표 설명 후보',
  `memo` text DEFAULT NULL COMMENT '처리 Item 내부 메모. workflow 처리 사유와 별도로 item 자체에 남기는 참고 메모',
  `raw_json` longtext DEFAULT NULL COMMENT '원천 row에서 가져온 원본 payload JSON. 재처리/추적/AI 학습 시 원천값 확인용',
  `mapped_payload_json` longtext DEFAULT NULL COMMENT '생성센터가 해석/보정한 업무 payload JSON. 거래처/계정/금액/보조계정 등 생성 전 의미 데이터',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '처리 Item 생성일시. 최초 backfill, split child 생성, merge result 생성 시점',
  `created_by` varchar(100) DEFAULT NULL COMMENT '처리 Item 생성 주체 ID. 사용자/시스템/batch/AI 생성 추적용',
  `updated_at` datetime DEFAULT NULL COMMENT '처리 Item 현재 상태 마지막 변경일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '처리 Item 현재 상태 마지막 변경 주체 ID',
  `deleted_at` datetime DEFAULT NULL COMMENT '처리 Item soft delete 일시. workflow lineage 삭제가 아닌 화면/처리 제외용',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '처리 Item soft delete 처리 주체 ID',
  PRIMARY KEY (`id`),
  KEY `idx_ledger_processing_items_source` (`source_table`,`source_id`,`deleted_at`,`sort_no`),
  KEY `idx_ledger_processing_items_type` (`source_type`,`deleted_at`),
  KEY `idx_ledger_processing_items_parent` (`parent_item_id`),
  KEY `idx_ledger_processing_items_source_item` (`source_item_id`),
  KEY `idx_ledger_processing_items_split_group` (`split_group_id`),
  KEY `idx_ledger_processing_items_merge_group` (`merge_group_id`),
  KEY `idx_ledger_processing_items_transaction_status` (`transaction_status`),
  KEY `idx_ledger_processing_items_voucher_status` (`voucher_status`),
  KEY `idx_ledger_processing_items_readiness_status` (`readiness_status`),
  KEY `idx_ledger_processing_items_domain_source` (`source_domain`,`source_type`,`source_id`),
  KEY `idx_ledger_processing_items_current` (`is_current`,`item_status`,`deleted_at`),
  KEY `idx_ledger_processing_items_lineage` (`lineage_root_id`),
  KEY `idx_ledger_processing_items_display_path` (`source_table`,`source_id`,`display_path`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='생성센터 workflow tree node 현재 상태 테이블. 원천 row를 업무적으로 해석, 분리, 병합, 보정, 거래/전표 생성 처리하는 핵심 엔티티';

-- Data for `ledger_processing_items`

-- ----------------------------
-- Table structure for `ledger_recent_journal_patterns`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_recent_journal_patterns`;
CREATE TABLE `ledger_recent_journal_patterns` (
  `id` char(36) NOT NULL,
  `pattern_hash` char(40) NOT NULL,
  `client_id` char(36) DEFAULT NULL,
  `transaction_direction` varchar(30) NOT NULL,
  `debit_account_id` char(36) NOT NULL,
  `credit_account_id` char(36) NOT NULL,
  `vat_account_id` char(36) DEFAULT NULL,
  `project_id` char(36) DEFAULT NULL,
  `usage_count` int(10) unsigned NOT NULL DEFAULT 0,
  `last_used_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_lrjp_pattern_hash` (`pattern_hash`),
  KEY `idx_lrjp_client_direction` (`client_id`,`transaction_direction`,`usage_count`,`last_used_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for `ledger_recent_journal_patterns`

-- ----------------------------
-- Table structure for `ledger_sub_accounts`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_sub_accounts`;
CREATE TABLE `ledger_sub_accounts` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `account_id` varchar(36) NOT NULL,
  `ref_type` varchar(20) NOT NULL COMMENT '보조계정 대상 타입 (CLIENT, PROJECT, EMPLOYEE, ACCOUNT, CARD 등)',
  `is_required` tinyint(1) NOT NULL DEFAULT 0 COMMENT '필수 여부 (1=필수, 0=선택)',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '생성일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자ID',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_account_ref_type` (`account_id`,`ref_type`),
  KEY `idx_account_id` (`account_id`) USING BTREE,
  CONSTRAINT `fk_sub_account` FOREIGN KEY (`account_id`) REFERENCES `ledger_accounts` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='ERP 회계 계정별 보조계정 정책 테이블 (입력 규칙 정의: 대상타입 및 필수여부)';

-- Data for `ledger_sub_accounts`

-- ----------------------------
-- Table structure for `ledger_transaction_files`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_transaction_files`;
CREATE TABLE `ledger_transaction_files` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `transaction_id` varchar(36) NOT NULL COMMENT '거래 ID',
  `file_path` varchar(500) NOT NULL COMMENT '파일 저장 경로',
  `file_name` varchar(255) DEFAULT NULL COMMENT '원본 파일명',
  `file_order` int(11) NOT NULL COMMENT '거래 한건의 파일 순번',
  `file_size` int(11) DEFAULT NULL COMMENT '파일 크기(byte)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성일시',
  `created_by` varchar(100) NOT NULL COMMENT '생성자',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tx_file_order` (`transaction_id`,`file_order`),
  KEY `idx_tx_files_transaction_id` (`transaction_id`),
  CONSTRAINT `fk_tx_files_transaction` FOREIGN KEY (`transaction_id`) REFERENCES `ledger_transactions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='거래 증빙 파일 테이블';

-- `ledger_transaction_files` data empty

-- ----------------------------
-- Table structure for `ledger_transaction_lines`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_transaction_lines`;
CREATE TABLE `ledger_transaction_lines` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '정렬/순서용 코드',
  `transaction_id` varchar(36) NOT NULL COMMENT '거래헤더 연결',
  `processing_item_id` varchar(36) DEFAULT NULL,
  `item_date` date NOT NULL COMMENT '거래 발생일',
  `item_name` varchar(255) NOT NULL COMMENT '품명',
  `specification` varchar(255) DEFAULT NULL COMMENT '규격',
  `unit_name` varchar(20) DEFAULT NULL COMMENT '단위',
  `quantity` decimal(15,3) NOT NULL DEFAULT 0.000 COMMENT '수량',
  `unit_price` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT '단가',
  `foreign_unit_price` decimal(15,2) DEFAULT NULL COMMENT '외화 단가',
  `foreign_amount` decimal(15,2) DEFAULT NULL COMMENT '외화 금액',
  `supply_amount` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT '공급가액',
  `vat_amount` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT '부가세액',
  `total_amount` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT '합계금액',
  `tax_type` varchar(20) DEFAULT NULL COMMENT '과세구분 (TAXABLE, ZERO, EXEMPT, SIMPLE, ETC)',
  `description` text DEFAULT NULL COMMENT '적요',
  `created_at` datetime DEFAULT NULL COMMENT '생성일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자',
  `updated_at` datetime DEFAULT NULL COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '삭제자',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tx_line` (`transaction_id`,`sort_no`),
  KEY `idx_ledger_transaction_items_transaction_id` (`transaction_id`),
  KEY `idx_ledger_transaction_items_deleted_at` (`deleted_at`),
  KEY `idx_ledger_transaction_lines_processing_item` (`processing_item_id`),
  CONSTRAINT `fk_ledger_transaction_items_transaction_id` FOREIGN KEY (`transaction_id`) REFERENCES `ledger_transactions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='회계 원본 거래 품목 상세 테이블';

-- `ledger_transaction_lines` data empty

-- ----------------------------
-- Table structure for `ledger_transaction_links`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_transaction_links`;
CREATE TABLE `ledger_transaction_links` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `transaction_id` varchar(36) NOT NULL,
  `voucher_id` varchar(36) NOT NULL,
  `match_amount` decimal(15,2) DEFAULT NULL COMMENT '매칭 금액 (부분매칭용)',
  `link_type` varchar(20) NOT NULL DEFAULT 'MANUAL' COMMENT '연결 방식 (AUTO, MANUAL)',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '사용 여부 (1: 사용, 0: 미사용)',
  `created_at` datetime DEFAULT NULL COMMENT '생성일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자',
  `updated_at` datetime DEFAULT NULL COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '삭제자',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tx_voucher_active` (`transaction_id`,`voucher_id`,`is_active`),
  KEY `idx_ledger_transaction_links_transaction_id` (`transaction_id`),
  KEY `idx_ledger_transaction_links_voucher_id` (`voucher_id`),
  KEY `idx_ledger_transaction_links_link_type` (`link_type`),
  KEY `idx_ledger_transaction_links_is_active` (`is_active`),
  KEY `idx_ledger_transaction_links_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_ledger_transaction_links_transaction_id` FOREIGN KEY (`transaction_id`) REFERENCES `ledger_transactions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ledger_transaction_links_voucher_id` FOREIGN KEY (`voucher_id`) REFERENCES `ledger_vouchers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='회계 원본 거래와 전표 연결 테이블';

-- `ledger_transaction_links` data empty

-- ----------------------------
-- Table structure for `ledger_transactions`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_transactions`;
CREATE TABLE `ledger_transactions` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '정렬/순서용 코드',
  `transaction_date` date NOT NULL COMMENT '작성일자(실제발생의정산기준)',
  `business_unit` varchar(30) NOT NULL COMMENT '사업구분 (CONSTRUCTION, ECOMMERCE, HQ)',
  `transaction_type` varchar(30) NOT NULL COMMENT '거래 유형 (GENERAL, SALARY, DAILY_WORK, BUSINESS_INCOME, SHOPPING, TRADE_IMPORT)',
  `transaction_direction` varchar(30) DEFAULT NULL COMMENT 'Transaction direction: PURCHASE, SALES, IN, OUT',
  `import_type` varchar(30) DEFAULT NULL COMMENT 'Source import type from seed rows',
  `client_id` varchar(36) DEFAULT NULL COMMENT '거래처',
  `project_id` varchar(36) DEFAULT NULL COMMENT '프로젝트',
  `description` text DEFAULT NULL COMMENT '설명',
  `currency` varchar(10) NOT NULL DEFAULT 'KRW' COMMENT '통화코드',
  `exchange_rate` decimal(15,6) DEFAULT NULL COMMENT '환율',
  `supply_amount` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT '공급가 합계',
  `vat_amount` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT '부가세 합계',
  `total_amount` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT '거래 총액 (매칭 기준)',
  `status` varchar(20) NOT NULL DEFAULT 'active' COMMENT '거래 자체 상태\r\ndraft     → 입력 상태 (수정 가능)\r\napproved  → 승인 완료 (수정 불가)\r\nrejected  → 반려 (수정 가능)',
  `match_status` varchar(20) NOT NULL DEFAULT 'none' COMMENT '전표연결 상태',
  `note` varchar(255) DEFAULT NULL COMMENT '비고',
  `memo` text DEFAULT NULL COMMENT '메모',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성일시',
  `created_by` varchar(100) NOT NULL COMMENT '생성자',
  `updated_at` datetime DEFAULT NULL COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '삭제자',
  PRIMARY KEY (`id`),
  KEY `idx_ledger_transactions_date` (`transaction_date`),
  KEY `idx_ledger_transactions_transaction_type` (`transaction_type`),
  KEY `idx_ledger_transactions_status` (`status`),
  KEY `idx_ledger_transactions_project_id` (`project_id`),
  KEY `idx_ledger_transactions_client_id` (`client_id`),
  KEY `idx_ledger_transactions_deleted_at` (`deleted_at`),
  KEY `idx_ledger_transactions_business_unit` (`business_unit`),
  KEY `idx_tx_main` (`business_unit`,`transaction_type`,`transaction_date`),
  KEY `idx_ledger_transactions_recommendation` (`business_unit`,`transaction_type`,`transaction_direction`,`import_type`,`client_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='회계 원본 거래 헤더 테이블';

-- `ledger_transactions` data empty

-- ----------------------------
-- Table structure for `ledger_voucher_line_refs`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_voucher_line_refs`;
CREATE TABLE `ledger_voucher_line_refs` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `voucher_line_id` varchar(36) NOT NULL COMMENT '전표라인 ID (ledger_voucher_lines.id 참조)',
  `ref_type` varchar(50) NOT NULL COMMENT '참조 유형 (CLIENT, PROJECT, ORDER, EMPLOYEE, CARD, ACCOUNT 등)',
  `ref_id` varchar(36) NOT NULL COMMENT '참조 대상 ID (ref_type 대상 테이블의 PK)',
  `is_primary` tinyint(1) DEFAULT 0 COMMENT '대표 참조 여부 (1=대표 참조, 0=보조 참조)',
  `created_at` datetime DEFAULT NULL COMMENT '생성일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_line_ref` (`voucher_line_id`,`ref_type`,`ref_id`),
  KEY `idx_line` (`voucher_line_id`),
  KEY `idx_ref` (`ref_type`,`ref_id`),
  CONSTRAINT `fk_line_refs_line` FOREIGN KEY (`voucher_line_id`) REFERENCES `ledger_voucher_lines` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='전표라인 참조 연결 테이블 (거래처, 프로젝트, 주문, 직원, 카드, 계좌 등 다중 참조 관리)';

-- Data for `ledger_voucher_line_refs`

-- ----------------------------
-- Table structure for `ledger_voucher_lines`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_voucher_lines`;
CREATE TABLE `ledger_voucher_lines` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '정렬/순서용 코드',
  `voucher_id` varchar(36) NOT NULL COMMENT '전표아이디',
  `processing_item_id` varchar(36) DEFAULT NULL,
  `account_id` varchar(36) DEFAULT NULL COMMENT '거래처',
  `line_no` int(11) NOT NULL COMMENT '라인 순서',
  `debit` decimal(15,2) DEFAULT 0.00 COMMENT '차변금액',
  `credit` decimal(15,2) DEFAULT 0.00 COMMENT '대변금액',
  `line_summary` varchar(255) DEFAULT NULL COMMENT '라인 적요',
  `recommend_source` varchar(30) DEFAULT NULL COMMENT 'Recommendation source',
  `recommend_confidence` tinyint(3) unsigned DEFAULT NULL COMMENT 'Recommendation confidence 0-100',
  `journal_rule_id` char(36) DEFAULT NULL COMMENT 'Matched journal rule ID',
  `recommend_reason` varchar(255) DEFAULT NULL COMMENT 'Recommendation reason',
  `is_user_modified` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'User changed recommended line',
  `created_at` datetime DEFAULT NULL COMMENT '생성일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자',
  `updated_at` datetime DEFAULT NULL COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_voucher_line` (`voucher_id`,`line_no`),
  UNIQUE KEY `uk_sort_no` (`sort_no`),
  KEY `idx_voucher` (`voucher_id`),
  KEY `fk_voucher_lines_account` (`account_id`),
  KEY `idx_ledger_voucher_lines_processing_item` (`processing_item_id`),
  CONSTRAINT `fk_voucher_lines_account` FOREIGN KEY (`account_id`) REFERENCES `ledger_accounts` (`id`),
  CONSTRAINT `fk_voucher_lines_voucher` FOREIGN KEY (`voucher_id`) REFERENCES `ledger_vouchers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='회계 전표 분개 라인';

-- Data for `ledger_voucher_lines`

