-- Table structure for `ledger_voucher_number_histories`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_voucher_number_histories`;
CREATE TABLE `ledger_voucher_number_histories` (
  `id` char(36) NOT NULL,
  `voucher_id` char(36) NOT NULL,
  `old_voucher_no` varchar(30) DEFAULT NULL,
  `new_voucher_no` varchar(30) NOT NULL,
  `reason` varchar(100) DEFAULT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_voucher_number_history_voucher` (`voucher_id`),
  KEY `idx_voucher_number_history_new_no` (`new_voucher_no`),
  KEY `idx_voucher_number_history_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for `ledger_voucher_number_histories`

-- ----------------------------
-- Table structure for `ledger_voucher_payments`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_voucher_payments`;
CREATE TABLE `ledger_voucher_payments` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '정렬/순서용 코드',
  `voucher_id` varchar(36) NOT NULL,
  `payment_type` varchar(50) NOT NULL COMMENT '결제유형 (ACCOUNT, CARD)',
  `payment_id` varchar(36) NOT NULL,
  `amount` decimal(15,2) NOT NULL COMMENT '결제금액',
  `direction` varchar(10) NOT NULL DEFAULT 'OUT' COMMENT '결제 방향 (IN=입금, OUT=출금)',
  `created_at` datetime DEFAULT NULL COMMENT '생성일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sort_no` (`sort_no`),
  KEY `idx_voucher` (`voucher_id`),
  KEY `idx_payment` (`payment_type`,`payment_id`),
  KEY `idx_payment_direction` (`direction`),
  CONSTRAINT `fk_payments_voucher` FOREIGN KEY (`voucher_id`) REFERENCES `ledger_vouchers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='전표 결제수단 테이블 (계좌/카드 결제 내역 및 입출금 방향 관리)';

-- Data for `ledger_voucher_payments`

-- ----------------------------
-- Table structure for `ledger_vouchers`
-- ----------------------------
DROP TABLE IF EXISTS `ledger_vouchers`;
CREATE TABLE `ledger_vouchers` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '정렬/순서용 코드',
  `voucher_no` varchar(20) NOT NULL COMMENT '전표번호 (YYYYMMDD-XXXX)',
  `voucher_date` date NOT NULL COMMENT '전표일자',
  `status` enum('draft','confirmed','reviewed','posted','closed','deleted') NOT NULL DEFAULT 'draft' COMMENT '상태(draft=임시저장, confirmed=검토요청, reviewed=검토완료, posted=승인, closed=마감, deleted=삭제)',
  `summary_text` varchar(255) DEFAULT NULL COMMENT '전표 요약',
  `note` text DEFAULT NULL COMMENT '비고',
  `memo` text DEFAULT NULL COMMENT '메모',
  `need_transaction` tinyint(1) NOT NULL DEFAULT 0 COMMENT '거래 연결 필요 여부',
  `reject_reason` text DEFAULT NULL COMMENT '반려 사유',
  `is_reversal` tinyint(1) NOT NULL DEFAULT 0 COMMENT '취소전표 여부',
  `reversal_of` varchar(36) DEFAULT NULL COMMENT '원본 전표 ID',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성일',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자',
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp() COMMENT '수정일',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '삭제자',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_voucher_no` (`voucher_no`),
  KEY `idx_voucher_date` (`voucher_date`),
  KEY `idx_status` (`status`),
  KEY `idx_reversal_of` (`reversal_of`),
  KEY `idx_status_date` (`status`,`voucher_date`),
  KEY `idx_created_by` (`created_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='회계 전표 헤더';

-- Data for `ledger_vouchers`

-- ----------------------------
-- Table structure for `system_bank_accounts`
-- ----------------------------
DROP TABLE IF EXISTS `system_bank_accounts`;
CREATE TABLE `system_bank_accounts` (
  `id` varchar(50) NOT NULL DEFAULT '' COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL AUTO_INCREMENT COMMENT '정렬 순서',
  `account_name` varchar(150) NOT NULL COMMENT '계좌명/별칭',
  `bank_name` varchar(100) DEFAULT NULL COMMENT '은행명',
  `account_number` varchar(100) DEFAULT NULL COMMENT '계좌번호',
  `account_holder` varchar(100) DEFAULT NULL COMMENT '예금주',
  `account_type` varchar(50) DEFAULT NULL COMMENT '계좌구분 (법인 / 개인 / 외화 등)',
  `currency` varchar(10) NOT NULL DEFAULT 'KRW' COMMENT '통화 (KRW, USD 등)',
  `bank_file` varchar(255) DEFAULT NULL COMMENT '통장사본 파일 경로',
  `note` varchar(255) DEFAULT NULL COMMENT '비고',
  `memo` text DEFAULT NULL COMMENT '메모',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '사용여부 (1:사용, 0:미사용)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성일시',
  `created_by` varchar(100) NOT NULL COMMENT '생성자 (USER:ID / SYSTEM:...)',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '삭제자',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`sort_no`) USING BTREE,
  KEY `idx_account_number` (`account_number`),
  KEY `idx_bank_name` (`bank_name`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='계좌 관리 테이블';

-- Data for `system_bank_accounts`

-- ----------------------------
-- Table structure for `system_brand_assets`
-- ----------------------------
DROP TABLE IF EXISTS `system_brand_assets`;
CREATE TABLE `system_brand_assets` (
  `id` varchar(50) NOT NULL DEFAULT '' COMMENT '고유 ID (UUID)',
  `asset_type` varchar(30) NOT NULL COMMENT '자산 유형 (main_logo | print_logo | favicon)',
  `db_path` varchar(255) NOT NULL COMMENT 'Storage DB 경로 (예: public://brand/xxxx.png)',
  `file_name` varchar(100) NOT NULL COMMENT '원본 또는 저장된 파일명',
  `mime_type` varchar(50) NOT NULL COMMENT '파일 MIME 타입',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '현재 사용 여부 (1: 사용중, 0: 비활성)',
  `created_at` datetime NOT NULL COMMENT '생성 일시',
  `created_by` char(100) NOT NULL COMMENT '생성자 사용자 ID',
  `updated_at` datetime DEFAULT NULL COMMENT '수정 일시',
  `updated_by` char(100) DEFAULT NULL COMMENT '수정자 사용자 ID',
  PRIMARY KEY (`id`),
  KEY `idx_brand_asset_type_active` (`asset_type`,`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci COMMENT='브랜드 로고 및 아이콘 자산 관리 테이블';

-- Data for `system_brand_assets`

-- ----------------------------
-- Table structure for `system_cards`
-- ----------------------------
DROP TABLE IF EXISTS `system_cards`;
CREATE TABLE `system_cards` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '정렬 순서',
  `card_name` varchar(150) NOT NULL COMMENT '카드명',
  `card_number` varchar(50) DEFAULT NULL COMMENT '카드번호 (마스킹 저장 권장)',
  `client_id` varchar(36) DEFAULT NULL,
  `account_id` varchar(36) DEFAULT NULL,
  `expiry_year` char(4) DEFAULT NULL,
  `expiry_month` char(2) DEFAULT NULL,
  `limit_amount` decimal(15,2) DEFAULT 0.00 COMMENT '한도금액',
  `card_file` varchar(255) DEFAULT NULL COMMENT '카드이미지 파일 경로',
  `note` varchar(255) DEFAULT NULL COMMENT '비고',
  `memo` text DEFAULT NULL COMMENT '메모',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '사용여부',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성일',
  `created_by` varchar(100) NOT NULL COMMENT '생성자',
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp() COMMENT '수정일',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '삭제자',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_account_id` (`account_id`),
  KEY `idx_deleted_at` (`deleted_at`),
  KEY `idx_is_active` (`is_active`),
  KEY `idx_client_id` (`client_id`),
  CONSTRAINT `fk_cards_account` FOREIGN KEY (`account_id`) REFERENCES `system_bank_accounts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cards_client` FOREIGN KEY (`client_id`) REFERENCES `system_clients` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='카드 관리 테이블';

-- Data for `system_cards`

-- ----------------------------
-- Table structure for `system_client_histories`
-- ----------------------------
DROP TABLE IF EXISTS `system_client_histories`;
CREATE TABLE `system_client_histories` (
  `id` char(36) NOT NULL,
  `client_id` varchar(36) NOT NULL,
  `field_name` varchar(100) NOT NULL,
  `old_value` text DEFAULT NULL,
  `new_value` text DEFAULT NULL,
  `source_type` varchar(80) DEFAULT NULL,
  `source_evidence_id` varchar(36) DEFAULT NULL,
  `changed_at` datetime NOT NULL DEFAULT current_timestamp(),
  `changed_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_client_changed_at` (`client_id`,`changed_at`),
  KEY `idx_source_evidence` (`source_evidence_id`),
  CONSTRAINT `fk_system_client_histories_client` FOREIGN KEY (`client_id`) REFERENCES `system_clients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Data for `system_client_histories`

-- ----------------------------
-- Table structure for `system_client_name_history`
-- ----------------------------
DROP TABLE IF EXISTS `system_client_name_history`;
CREATE TABLE `system_client_name_history` (
  `id` varchar(50) NOT NULL DEFAULT '' COMMENT '고유 ID (UUID)',
  `client_id` varchar(36) NOT NULL COMMENT '거래처 ID',
  `old_company_name` varchar(200) NOT NULL COMMENT '이전 상호',
  `new_company_name` varchar(200) NOT NULL COMMENT '변경 상호',
  `changed_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '변경일시',
  `changed_by` varchar(100) DEFAULT NULL COMMENT '변경자',
  PRIMARY KEY (`id`),
  KEY `idx_client` (`client_id`),
  CONSTRAINT `fk_client_history_client` FOREIGN KEY (`client_id`) REFERENCES `system_clients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='거래처 상호 변경 이력';

-- Data for `system_client_name_history`

-- ----------------------------
-- Table structure for `system_clients`
-- ----------------------------
DROP TABLE IF EXISTS `system_clients`;
CREATE TABLE `system_clients` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '정렬순서 (자동 증가 또는 수동 정렬용)',
  `client_name` varchar(100) NOT NULL COMMENT '거래처명',
  `company_name` varchar(100) DEFAULT NULL COMMENT '상호',
  `registration_date` date DEFAULT NULL COMMENT '등록일자',
  `client_type` varchar(20) DEFAULT NULL COMMENT '거래유형 (매입, 매출, 겸용, 협력업체)',
  `merchant_raw_name` varchar(200) DEFAULT NULL COMMENT '원본 가맹점명 (카드/영수증 원문)',
  `normalized_name` varchar(200) DEFAULT NULL COMMENT '정규화 이름 (매칭용)',
  `client_grade` varchar(50) DEFAULT NULL COMMENT '거래처등급 (A, B, C 등)',
  `business_number` varchar(20) DEFAULT NULL COMMENT '사업자등록번호',
  `rrn` varchar(255) DEFAULT NULL COMMENT '법인번호 또는 주민등록번호',
  `rrn_image` varchar(255) DEFAULT NULL COMMENT '등록증이미지',
  `business_certificate` varchar(255) DEFAULT NULL COMMENT '사업자등록증 파일 경로',
  `business_type` varchar(50) DEFAULT NULL COMMENT '업태',
  `business_category` varchar(50) DEFAULT NULL COMMENT '업종',
  `business_status` varchar(20) DEFAULT NULL COMMENT '사업자등록 상태 (등록, 휴업, 폐업 등)',
  `ceo_name` varchar(50) DEFAULT NULL COMMENT '대표자명',
  `ceo_phone` varchar(30) DEFAULT NULL COMMENT '대표자 연락처',
  `manager_name` varchar(50) DEFAULT NULL COMMENT '담당자명',
  `manager_phone` varchar(30) DEFAULT NULL COMMENT '담당자 연락처',
  `phone` varchar(30) DEFAULT NULL COMMENT '전화번호',
  `fax` varchar(30) DEFAULT NULL COMMENT '팩스번호',
  `email` varchar(100) DEFAULT NULL COMMENT '이메일',
  `address` varchar(255) DEFAULT NULL COMMENT '주소',
  `address_detail` varchar(255) DEFAULT NULL COMMENT '상세주소',
  `homepage` varchar(255) DEFAULT NULL COMMENT '홈페이지',
  `client_category` varchar(50) DEFAULT NULL COMMENT '거래처분류 (매입, 매출, 협력업체 등)',
  `bank_name` varchar(100) DEFAULT NULL COMMENT '은행명',
  `account_number` varchar(50) DEFAULT NULL COMMENT '계좌번호',
  `account_holder` varchar(100) DEFAULT NULL COMMENT '예금주',
  `bank_file` varchar(255) DEFAULT NULL COMMENT '통장사본 파일',
  `trade_category` varchar(20) DEFAULT NULL COMMENT '거래구분 (국내, 수입, 수출)',
  `default_account_id` char(36) DEFAULT NULL COMMENT '자동분개 추천 기본계정과목 ID',
  `tax_type` varchar(20) DEFAULT NULL COMMENT '과세구분 (과세, 면세, 영세)',
  `payment_term` varchar(50) DEFAULT NULL COMMENT '결제조건 (현금, 월말, 30일 등)',
  `item_category` varchar(100) DEFAULT NULL COMMENT '취급품목',
  `note` varchar(255) DEFAULT NULL COMMENT '비고',
  `memo` text DEFAULT NULL COMMENT '관리자 메모',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '활성상태 (1=활성, 0=비활성)',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '등록일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자ID',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자ID',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '삭제자ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_client_name` (`client_name`) USING BTREE,
  KEY `idx_business_number` (`business_number`) USING BTREE,
  KEY `idx_is_active` (`is_active`) USING BTREE,
  KEY `idx_code` (`sort_no`) USING BTREE,
  KEY `idx_normalized_name` (`normalized_name`(191)),
  KEY `idx_system_clients_default_account_id` (`default_account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='거래처 관리 테이블 (매입/매출/협력업체 등)';

-- Data for `system_clients`

-- ----------------------------
-- Table structure for `system_codes`
-- ----------------------------
DROP TABLE IF EXISTS `system_codes`;
CREATE TABLE `system_codes` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '정렬순서 (자동 증가 또는 수동 정렬용)',
  `code_group` varchar(50) NOT NULL COMMENT '코드 그룹 (CLIENT_TYPE, PAYMENT_TERM, REF_TYPE 등)',
  `group_name` varchar(100) NOT NULL COMMENT '코드그룹 UI 표시명 (예: 사업, 거래처, 거래, 자료유형 등)',
  `code` varchar(50) NOT NULL COMMENT '코드값 (실제 저장 값)',
  `code_name` varchar(100) NOT NULL COMMENT '코드명 (사용자 표시용)',
  `note` varchar(255) DEFAULT NULL COMMENT '비고',
  `memo` text DEFAULT NULL COMMENT '관리자 메모',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '활성상태 (1=사용, 0=미사용)',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '등록일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자ID',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자ID',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '삭제자ID',
  `extra_data` text DEFAULT NULL COMMENT '추가 속성 (JSON 문자열)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uq_code_group_code` (`code_group`,`code`) USING BTREE COMMENT '코드그룹 + 코드 유니크',
  KEY `idx_code_group` (`code_group`) USING BTREE,
  KEY `idx_code_name` (`code_name`) USING BTREE,
  KEY `idx_is_active` (`is_active`) USING BTREE,
  KEY `idx_sort_no` (`sort_no`) USING BTREE,
  KEY `idx_group_sort` (`code_group`,`sort_no`),
  KEY `idx_system_codes_group_name_sort` (`group_name`,`code_group`,`sort_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='기준정보 코드 테이블 (공통 코드 관리: 거래유형, 결제조건, REF_TYPE 등)';

-- Data for `system_codes`

-- ----------------------------
-- Table structure for `system_company`
-- ----------------------------
DROP TABLE IF EXISTS `system_company`;
CREATE TABLE `system_company` (
  `id` varchar(50) NOT NULL DEFAULT '' COMMENT '고유 ID (UUID)',
  `company_name_ko` varchar(100) NOT NULL COMMENT '회사명(한글)',
  `company_name_en` varchar(100) DEFAULT NULL COMMENT '회사명(영문)',
  `ceo_name` varchar(50) DEFAULT NULL COMMENT '대표자명',
  `biz_number` varchar(20) DEFAULT NULL COMMENT '사업자등록번호',
  `corp_number` varchar(20) DEFAULT NULL COMMENT '법인등록번호',
  `found_date` date DEFAULT NULL COMMENT '설립일',
  `biz_type` varchar(100) DEFAULT NULL COMMENT '업태',
  `biz_item` varchar(100) DEFAULT NULL COMMENT '종목',
  `addr_main` varchar(255) DEFAULT NULL COMMENT '본점주소',
  `addr_detail` varchar(255) DEFAULT NULL COMMENT '상세주소',
  `tel` varchar(30) DEFAULT NULL COMMENT '전화번호',
  `fax` varchar(30) DEFAULT NULL COMMENT '팩스번호',
  `tax_email` varchar(100) DEFAULT NULL COMMENT '전자세금계산서 이메일',
  `sub_email` varchar(100) DEFAULT NULL COMMENT '서브 이메일',
  `company_website` varchar(100) DEFAULT NULL COMMENT '회사 공식 홈페이지 URL',
  `sns_instagram` varchar(100) DEFAULT NULL COMMENT '회사 공식 인스타그램',
  `company_about` text DEFAULT NULL COMMENT '회사소개',
  `company_history` text DEFAULT NULL COMMENT '연혁',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성일',
  `created_by` varchar(50) NOT NULL DEFAULT '' COMMENT '생성자(user_id)',
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp() COMMENT '수정일',
  `updated_by` varchar(50) DEFAULT NULL COMMENT '수정자(user_id)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci COMMENT='시스템 회사 기본 정보';

-- Data for `system_company`

-- ----------------------------
-- Table structure for `system_coverimage_assets`
-- ----------------------------
DROP TABLE IF EXISTS `system_coverimage_assets`;
CREATE TABLE `system_coverimage_assets` (
  `id` varchar(50) NOT NULL DEFAULT '' COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL,
  `year` varchar(4) NOT NULL COMMENT '년도 (예: 2025)',
  `title` varchar(255) DEFAULT NULL COMMENT '타이틀',
  `alt` varchar(100) NOT NULL COMMENT '대체 텍스트 (이미지 설명)',
  `description` varchar(255) DEFAULT NULL COMMENT '설명',
  `src` varchar(255) NOT NULL COMMENT '이미지 경로 (/uploads/cover/...)',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 여부(1=사용중, 0=휴지통/비활성)',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '등록일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '등록자',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자',
  `deleted_at` datetime DEFAULT NULL COMMENT '휴지통 이동 일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '휴지통 이동 처리자 사용자 ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_year` (`year`) USING BTREE,
  KEY `idx_code` (`sort_no`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='홈페이지 메인(로그인 전) 커버 이미지 관리 테이블 (UUID + 순번 구조)';

-- Data for `system_coverimage_assets`

-- ----------------------------
-- Table structure for `system_file_upload_policies`
-- ----------------------------
DROP TABLE IF EXISTS `system_file_upload_policies`;
CREATE TABLE `system_file_upload_policies` (
  `id` varchar(50) NOT NULL DEFAULT '' COMMENT '고유 ID (UUID)',
  `policy_key` varchar(50) NOT NULL COMMENT '정책 고유 키 (코드)',
  `policy_name` varchar(100) NOT NULL COMMENT '정책 이름',
  `bucket` varchar(100) NOT NULL COMMENT '저장 bucket (public://profile 등)',
  `allowed_ext` text NOT NULL COMMENT '허용 확장자 (csv: jpg,png,pdf)',
  `allowed_mime` text DEFAULT NULL COMMENT '허용 MIME (csv)',
  `max_size_mb` int(10) unsigned NOT NULL COMMENT '최대 업로드 용량(MB)',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 여부',
  `description` varchar(255) DEFAULT NULL COMMENT '설명',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `created_by` varchar(50) NOT NULL DEFAULT '' COMMENT '생성자 사용자 ID (employees.id)',
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `updated_by` varchar(50) DEFAULT NULL COMMENT '수정자 사용자 ID (employees.id)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_policy_key` (`policy_key`),
  KEY `idx_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='파일 업로드 정책 정의';

-- Data for `system_file_upload_policies`

-- ----------------------------
-- Table structure for `system_menu_registry`
-- ----------------------------
DROP TABLE IF EXISTS `system_menu_registry`;
CREATE TABLE `system_menu_registry` (
  `menu_key` varchar(191) NOT NULL COMMENT '공통 menu 식별키',
  `page_key` varchar(191) DEFAULT NULL COMMENT '연결된 system_page_registry.page_key',
  `module_key` varchar(100) NOT NULL COMMENT '최상위 모듈 key',
  `menu_label` varchar(100) NOT NULL COMMENT '메뉴 표시명',
  `module_order` int(11) NOT NULL DEFAULT 999 COMMENT '모듈 정렬순서',
  `menu_order` int(11) NOT NULL DEFAULT 999 COMMENT '메뉴 그룹 정렬순서',
  `page_order` int(11) NOT NULL DEFAULT 999 COMMENT '페이지 정렬순서',
  `menu_icon` varchar(100) DEFAULT NULL COMMENT '메뉴 아이콘 클래스',
  `default_entry` varchar(255) DEFAULT NULL COMMENT '대표 진입 URL',
  `is_menu` tinyint(1) NOT NULL DEFAULT 1 COMMENT '메뉴 여부',
  `visible_in_sidebar` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Sidebar 노출 여부',
  `visible_in_settings` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Settings Menu 노출 여부',
  `visible_in_sitemap` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'SiteMap 노출 여부',
  `visible_in_navbar` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Navbar 노출 여부',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 여부',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성일시',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  PRIMARY KEY (`menu_key`),
  KEY `idx_system_menu_registry_page_key` (`page_key`),
  KEY `idx_system_menu_registry_module` (`module_key`),
  KEY `idx_system_menu_registry_sidebar` (`visible_in_sidebar`),
  KEY `idx_system_menu_registry_settings` (`visible_in_settings`),
  KEY `idx_system_menu_registry_sitemap` (`visible_in_sitemap`),
  KEY `idx_system_menu_registry_navbar` (`visible_in_navbar`),
  KEY `idx_system_menu_registry_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='ERP 공통 Menu Registry';

-- Data for `system_menu_registry`

-- ----------------------------
-- Table structure for `system_notifications`
-- ----------------------------
DROP TABLE IF EXISTS `system_notifications`;
CREATE TABLE `system_notifications` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `recipient_user_id` varchar(36) NOT NULL COMMENT '수신 사용자 ID (auth_users.id)',
  `actor_user_id` varchar(36) DEFAULT NULL COMMENT '행위자 사용자 ID',
  `action_type` varchar(50) NOT NULL COMMENT '행동 유형 (approve, reject, create 등)',
  `ref_table` varchar(100) DEFAULT NULL COMMENT '관련 테이블 (ledger_vouchers 등)',
  `ref_id` varchar(36) DEFAULT NULL COMMENT '관련 데이터 ID',
  `title` varchar(255) NOT NULL COMMENT '알림 제목',
  `message` text NOT NULL COMMENT '알림 메시지',
  `is_read` tinyint(1) NOT NULL DEFAULT 0 COMMENT '읽음 여부',
  `read_at` datetime DEFAULT NULL COMMENT '읽은 시간',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성일시',
  PRIMARY KEY (`id`),
  KEY `idx_recipient` (`recipient_user_id`),
  KEY `idx_actor` (`actor_user_id`),
  KEY `idx_is_read` (`is_read`),
  KEY `idx_created_at` (`created_at`),
  CONSTRAINT `fk_notification_actor` FOREIGN KEY (`actor_user_id`) REFERENCES `auth_users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_notification_recipient` FOREIGN KEY (`recipient_user_id`) REFERENCES `auth_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='ERP 알림 테이블';

-- Data for `system_notifications`

-- ----------------------------
-- Table structure for `system_page_registry`
-- ----------------------------
DROP TABLE IF EXISTS `system_page_registry`;
CREATE TABLE `system_page_registry` (
  `page_key` varchar(191) NOT NULL COMMENT '공통 page 식별자',
  `module_key` varchar(100) NOT NULL COMMENT '최상위 모듈 key',
  `module_label` varchar(100) NOT NULL COMMENT '최상위 모듈 표시명',
  `menu_key` varchar(191) NOT NULL COMMENT '메뉴 key',
  `menu_label` varchar(100) NOT NULL COMMENT '메뉴 표시명',
  `page_label` varchar(100) NOT NULL COMMENT '화면 표시명',
  `page_description` varchar(255) DEFAULT NULL COMMENT '화면 설명',
  `breadcrumb` varchar(255) NOT NULL COMMENT '모듈 > 메뉴 > 화면 경로',
  `default_route_key` varchar(191) DEFAULT NULL COMMENT '대표 WEB route key',
  `default_route_url` varchar(255) DEFAULT NULL COMMENT '대표 WEB route URL',
  `source_description` varchar(255) NOT NULL COMMENT '초기 생성에 사용한 source description',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 여부',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성일시',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  PRIMARY KEY (`page_key`),
  KEY `idx_system_page_registry_module` (`module_key`),
  KEY `idx_system_page_registry_menu` (`menu_key`),
  KEY `idx_system_page_registry_default_route_key` (`default_route_key`),
  KEY `idx_system_page_registry_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='ERP 공통 Page Registry';

-- Data for `system_page_registry`

-- ----------------------------
-- Table structure for `system_projects`
-- ----------------------------
DROP TABLE IF EXISTS `system_projects`;
CREATE TABLE `system_projects` (
  `id` varchar(36) NOT NULL DEFAULT '' COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL,
  `project_name` varchar(100) DEFAULT NULL COMMENT '프로젝트명 (내부 식별용)',
  `client_id` varchar(36) DEFAULT NULL COMMENT '거래처 ID (ledger_clients.id FK)',
  `employee_id` varchar(36) DEFAULT NULL COMMENT '담당 직원 ID (user_profiles.id FK)',
  `site_agent` varchar(100) DEFAULT NULL COMMENT '현장대리인',
  `contract_type` varchar(50) DEFAULT NULL COMMENT '계약형태 (예: 도급, 하도급 등)',
  `contract_method` varchar(50) DEFAULT NULL,
  `director` varchar(50) DEFAULT NULL COMMENT '소장',
  `manager` varchar(50) DEFAULT NULL COMMENT '실장',
  `business_type` varchar(50) DEFAULT NULL COMMENT '업종',
  `housing_type` varchar(50) DEFAULT NULL COMMENT '주력분야',
  `construction_name` varchar(100) DEFAULT NULL COMMENT '공사명 (프로젝트 정식 명칭)',
  `site_region_city` varchar(50) DEFAULT NULL COMMENT '공사지역 (시도)',
  `site_region_district` varchar(50) DEFAULT NULL COMMENT '공사지역 (시군구)',
  `site_region_address` varchar(255) DEFAULT NULL COMMENT '공사지역 주소',
  `site_region_address_detail` varchar(255) DEFAULT NULL COMMENT '공사지역 주소',
  `work_type` varchar(50) DEFAULT NULL COMMENT '공종 (예: 석공사, 토목공사 등)',
  `work_subtype` varchar(50) DEFAULT NULL COMMENT '공종 세분류',
  `work_detail_type` varchar(100) DEFAULT NULL COMMENT '세부 공사종류',
  `contract_work_type` varchar(50) DEFAULT NULL COMMENT '도급 종류 (직영, 하도 등)',
  `bid_type` varchar(50) DEFAULT NULL COMMENT '입찰형태 (지명, 경쟁, 수의 등)',
  `client_name` varchar(100) DEFAULT NULL COMMENT '발주자명',
  `client_type` varchar(50) DEFAULT NULL COMMENT '발주자 분류 (공공, 민간 등)',
  `permit_agency` varchar(100) DEFAULT NULL COMMENT '인허가기관',
  `permit_date` date DEFAULT NULL COMMENT '인허가일자',
  `contract_date` date DEFAULT NULL COMMENT '계약일자',
  `start_date` date DEFAULT NULL COMMENT '착공일자',
  `completion_date` date DEFAULT NULL COMMENT '준공일자',
  `bid_notice_date` date DEFAULT NULL COMMENT '입찰공고일',
  `initial_contract_amount` decimal(18,2) DEFAULT NULL COMMENT '최초 계약금액(공급가액)',
  `authorized_company_seal` varchar(100) DEFAULT NULL COMMENT '사용인감명',
  `note` varchar(255) DEFAULT NULL COMMENT '비고',
  `memo` text DEFAULT NULL COMMENT '상세 메모',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '진행상태 (1=진행중, 0=완료/종료)',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '등록일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '등록자ID',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자ID',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '삭제자ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_client_id` (`client_id`) USING BTREE,
  KEY `idx_employee_id` (`employee_id`) USING BTREE,
  KEY `idx_is_active` (`is_active`) USING BTREE,
  KEY `idx_manage_name` (`project_name`) USING BTREE,
  KEY `idx_code` (`sort_no`) USING BTREE,
  CONSTRAINT `fk_projects_client` FOREIGN KEY (`client_id`) REFERENCES `system_clients` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_projects_employee` FOREIGN KEY (`employee_id`) REFERENCES `user_employees` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='프로젝트(현장/공사) 관리 테이블 (UUID + 순번 구조)';

-- Data for `system_projects`

-- ----------------------------
-- Table structure for `system_settings_config`
-- ----------------------------
DROP TABLE IF EXISTS `system_settings_config`;
CREATE TABLE `system_settings_config` (
  `config_key` varchar(100) NOT NULL COMMENT '환경설정 키(PK).\r\n네이밍 규칙: {category_prefix}_{name}\r\n예: session_timeout, site_slogan, api_enabled, security_password_min',
  `config_value` text DEFAULT NULL COMMENT '환경설정 값.\r\n모든 값은 문자열(TEXT)로 저장.\r\n숫자/Boolean/JSON 타입 변환은 Service 계층에서 처리.\r\n예: "3600", "1", "Noto Sans KR", "1.1.1.1,2.2.2.2", JSON 문자열',
  `category` varchar(50) NOT NULL COMMENT '설정 분류(필수).\r\n화면 탭 / 기능 그룹 기준.\r\n권장값:\r\nSITE | SESSION | API | SECURITY | UPLOAD | BACKUP | LOG | SYSTEM\r\nENUM 미사용 (확장성 우선)',
  `description` varchar(255) DEFAULT NULL COMMENT '관리자 화면 표시용 설명.\r\n예: "세션 유지 시간(분)", "API 요청 제한(분당)"',
  `is_editable` tinyint(1) DEFAULT 1 COMMENT '수정 가능 여부.\r\n1 = 관리자 화면/API에서 수정 가능\r\n0 = 시스템 고정값 (UI/REST에서 수정 금지 권장)',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '등록 일시(최초 생성 시각)',
  `created_by` varchar(100) DEFAULT NULL COMMENT '등록자 ID(Users UUID 등). 자동기록 권장',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정 일시(값 변경 시 자동 갱신)',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자 ID(Users UUID 등). 자동기록 권장',
  PRIMARY KEY (`config_key`) USING BTREE,
  KEY `idx_category` (`category`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='시스템 전역 설정(Key-Value) 테이블.\r\n단일 테이블로 SITE / SESSION / API / SECURITY / UPLOAD / BACKUP / LOG 등\r\n모든 시스템 설정을 통합 관리.\r\n타입 캐스팅은 Service 계층 책임으로 설계';

-- Data for `system_settings_config`

-- ----------------------------
-- Table structure for `system_work_team_members`
-- ----------------------------
DROP TABLE IF EXISTS `system_work_team_members`;
CREATE TABLE `system_work_team_members` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `team_id` varchar(36) NOT NULL COMMENT '작업팀 ID',
  `client_id` varchar(36) NOT NULL COMMENT '거래처 ID',
  `role` varchar(50) DEFAULT NULL COMMENT '역할 (철근, 목공 등)',
  `note` varchar(255) DEFAULT NULL,
  `joined_at` datetime DEFAULT current_timestamp(),
  `left_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` varchar(100) DEFAULT NULL,
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `updated_by` varchar(100) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_team_client` (`team_id`,`client_id`),
  KEY `idx_team_id` (`team_id`),
  KEY `idx_client_id` (`client_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='작업팀 구성원 (거래처 기반)';

-- `system_work_team_members` data empty

-- ----------------------------
-- Table structure for `system_work_teams`
-- ----------------------------
DROP TABLE IF EXISTS `system_work_teams`;
CREATE TABLE `system_work_teams` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '정렬순서',
  `team_name` varchar(100) NOT NULL COMMENT '작업팀명',
  `team_leader_client_id` varchar(36) DEFAULT NULL COMMENT '팀장 (거래처 ID)',
  `note` varchar(255) DEFAULT NULL COMMENT '비고',
  `memo` text DEFAULT NULL COMMENT '관리자 메모',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '활성상태 (1=사용, 0=미사용)',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '등록일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자ID',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자ID',
  `deleted_at` datetime DEFAULT NULL COMMENT '삭제일시',
  `deleted_by` varchar(100) DEFAULT NULL COMMENT '삭제자ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_team_name` (`team_name`) USING BTREE,
  KEY `idx_is_active` (`is_active`) USING BTREE,
  KEY `idx_sort_no` (`sort_no`) USING BTREE,
  KEY `idx_team_leader` (`team_leader_client_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='작업팀 관리 테이블 (프로젝트/스케줄용 동적 팀)';

-- Data for `system_work_teams`

-- ----------------------------
-- Table structure for `user_approval_request_steps`
-- ----------------------------
DROP TABLE IF EXISTS `user_approval_request_steps`;
CREATE TABLE `user_approval_request_steps` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `request_id` varchar(36) NOT NULL COMMENT '결재 요청 ID (user_approval_requests.id)',
  `sequence` int(11) NOT NULL COMMENT '결재 순서',
  `approver_id` varchar(36) NOT NULL COMMENT '해당 단계 결재자 ID',
  `status` enum('pending','approved','rejected') NOT NULL DEFAULT 'pending' COMMENT '결재 상태',
  `approved_at` datetime DEFAULT NULL COMMENT '승인 일시',
  `rejected_at` datetime DEFAULT NULL COMMENT '반려 일시',
  `comment` text DEFAULT NULL COMMENT '결재 의견',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 여부',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성 일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정 일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_request_sequence` (`request_id`,`sequence`),
  KEY `fk_request_steps_approver` (`approver_id`),
  CONSTRAINT `fk_request_steps_approver` FOREIGN KEY (`approver_id`) REFERENCES `auth_users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_request_steps_request` FOREIGN KEY (`request_id`) REFERENCES `user_approval_requests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='실제 결재 단계 진행 기록';

-- `user_approval_request_steps` data empty

-- ----------------------------
-- Table structure for `user_approval_requests`
-- ----------------------------
DROP TABLE IF EXISTS `user_approval_requests`;
CREATE TABLE `user_approval_requests` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `template_id` varchar(36) NOT NULL COMMENT '사용된 결재 템플릿 ID',
  `document_id` varchar(36) NOT NULL COMMENT 'ERP 본문 문서 ID (지출결의서, 휴가신청서 등)',
  `requester_id` varchar(36) NOT NULL COMMENT '기안자 ID (auth_users.id)',
  `status` enum('pending','in_progress','approved','rejected') NOT NULL DEFAULT 'pending' COMMENT '전체 결재 상태',
  `current_step` int(11) NOT NULL DEFAULT 1 COMMENT '현재 진행중인 단계 번호',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 여부 (삭제 대신 비활성화)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '기안 일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '기안자 ID',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정 일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자 ID',
  PRIMARY KEY (`id`),
  KEY `idx_document` (`document_id`),
  KEY `fk_request_template` (`template_id`),
  CONSTRAINT `fk_request_template` FOREIGN KEY (`template_id`) REFERENCES `user_approval_templates` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='결재 요청 본문 (기안)';

-- `user_approval_requests` data empty

-- ----------------------------
-- Table structure for `user_approval_template_steps`
-- ----------------------------
DROP TABLE IF EXISTS `user_approval_template_steps`;
CREATE TABLE `user_approval_template_steps` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '결재 순서 (1부터 시작)',
  `template_id` varchar(36) NOT NULL COMMENT '결재 템플릿 ID (user_approval_templates.id)',
  `step_name` varchar(100) DEFAULT NULL COMMENT '단계 이름 (예: 1차 결재, 부서장 승인 등)',
  `role_id` varchar(36) DEFAULT NULL COMMENT '결재자 역할 ID (auth_roles.id)',
  `approver_id` varchar(36) DEFAULT NULL COMMENT '특정 결재자 ID 지정 (auth_users.id)',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 여부 (1=활성, 0=비활성)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '등록 일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '등록자 ID',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정 일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자 ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_sequence` (`template_id`,`sort_no`) USING BTREE,
  KEY `fk_template_steps_role` (`role_id`),
  KEY `fk_template_steps_approver` (`approver_id`),
  CONSTRAINT `fk_template_steps_approver` FOREIGN KEY (`approver_id`) REFERENCES `auth_users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_template_steps_role` FOREIGN KEY (`role_id`) REFERENCES `auth_roles` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_template_steps_template` FOREIGN KEY (`template_id`) REFERENCES `user_approval_templates` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='결재 템플릿 단계 정의';

-- Data for `user_approval_template_steps`

-- ----------------------------
-- Table structure for `user_approval_templates`
-- ----------------------------
DROP TABLE IF EXISTS `user_approval_templates`;
CREATE TABLE `user_approval_templates` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '순번',
  `template_key` varchar(50) DEFAULT NULL COMMENT '템플릿 고유 키 (unique, 예: expense, vacation)',
  `template_name` varchar(100) NOT NULL COMMENT '템플릿 이름 (예: 지출결의서)',
  `document_type` varchar(100) DEFAULT NULL COMMENT '문서 유형 (예: 지출결의서, 구매요청서, 휴가신청서 등)',
  `description` text DEFAULT NULL COMMENT '템플릿 설명',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 여부 (1=활성, 0=비활성)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '등록 일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '등록자 ID (auth_users.id)',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정 일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자 ID (auth_users.id)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_key` (`template_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='결재 템플릿 마스터';

-- Data for `user_approval_templates`

-- ----------------------------
-- Table structure for `user_departments`
-- ----------------------------
DROP TABLE IF EXISTS `user_departments`;
CREATE TABLE `user_departments` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL AUTO_INCREMENT COMMENT '순번 (AUTO_INCREMENT)',
  `dept_name` varchar(100) NOT NULL COMMENT '부서명',
  `manager_id` varchar(36) DEFAULT NULL COMMENT '부서장 ID (auth_users.id 참조)',
  `description` varchar(255) DEFAULT NULL COMMENT '부서 설명',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '활성 상태 (1=활성, 0=비활성)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '등록일',
  `created_by` varchar(100) DEFAULT NULL COMMENT '동록자ID',
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp() COMMENT '수정일',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_code` (`sort_no`) USING BTREE,
  KEY `idx_manager_id` (`manager_id`) USING BTREE,
  CONSTRAINT `fk_user_departments_manager` FOREIGN KEY (`manager_id`) REFERENCES `auth_users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='조직(부서) 관리 테이블 (UUID + 순번 구조, 자체 참조 계층형 구조)';

-- Data for `user_departments`

-- ----------------------------
-- Table structure for `user_employees`
-- ----------------------------
DROP TABLE IF EXISTS `user_employees`;
CREATE TABLE `user_employees` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `sort_no` int(11) NOT NULL COMMENT '순서용코드',
  `user_id` varchar(36) NOT NULL COMMENT '사용자 ID (auth_users.id FK)',
  `client_id` varchar(36) DEFAULT NULL COMMENT '회계용 거래처 ID (clients.id FK)',
  `employee_name` varchar(50) NOT NULL COMMENT '직원 이름',
  `phone` varchar(20) DEFAULT NULL COMMENT '연락처',
  `address` varchar(255) DEFAULT NULL COMMENT '주소',
  `address_detail` varchar(255) DEFAULT NULL COMMENT '상세주소',
  `department_id` varchar(36) DEFAULT NULL COMMENT '부서 ID (user_departments.id FK)',
  `position_id` varchar(36) DEFAULT NULL COMMENT '직위 ID (user_positions.id FK)',
  `doc_hire_date` date DEFAULT NULL COMMENT '문서상 입사일',
  `real_hire_date` date DEFAULT NULL COMMENT '실제 입사일',
  `doc_retire_date` date DEFAULT NULL COMMENT '문서상 퇴사일',
  `real_retire_date` date DEFAULT NULL COMMENT '실제 퇴사일',
  `rrn` varchar(255) DEFAULT NULL COMMENT '주민등록번호 암호화 저장값',
  `rrn_image` varchar(255) DEFAULT NULL COMMENT '신분증 파일 경로(공개 금지)',
  `emergency_phone` varchar(20) DEFAULT NULL COMMENT '비상연락처',
  `profile_image` varchar(255) DEFAULT NULL COMMENT '프로필 사진 경로',
  `certificate_name` varchar(50) DEFAULT NULL COMMENT '대표 자격증 이름',
  `certificate_file` varchar(255) DEFAULT NULL COMMENT '대표 자격증 파일 경로',
  `bank_name` varchar(100) DEFAULT NULL COMMENT '은행명',
  `account_number` varchar(50) DEFAULT NULL COMMENT '계좌번호',
  `account_holder` varchar(100) DEFAULT NULL COMMENT '예금주',
  `bank_file` varchar(255) DEFAULT NULL COMMENT '통장사본 파일',
  `note` varchar(255) DEFAULT NULL COMMENT '비고',
  `memo` text DEFAULT NULL COMMENT '관리자 메모',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '생성일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자ID',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_department_id` (`department_id`) USING BTREE,
  KEY `idx_position_id` (`position_id`) USING BTREE,
  KEY `idx_code` (`sort_no`) USING BTREE,
  KEY `idx_client_id` (`client_id`),
  CONSTRAINT `fk_user_employees_client` FOREIGN KEY (`client_id`) REFERENCES `system_clients` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_user_profiles_department` FOREIGN KEY (`department_id`) REFERENCES `user_departments` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_user_profiles_position` FOREIGN KEY (`position_id`) REFERENCES `user_positions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_user_profiles_user` FOREIGN KEY (`user_id`) REFERENCES `auth_users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='직원 인사 / 프로필 관리 테이블 (UUID + 순번 구조, 부서/직위 FK 연동)';

-- Data for `user_employees`

-- ----------------------------
-- Table structure for `user_external_accounts`
-- ----------------------------
DROP TABLE IF EXISTS `user_external_accounts`;
CREATE TABLE `user_external_accounts` (
  `id` varchar(36) NOT NULL COMMENT '고유 ID (UUID)',
  `user_id` varchar(36) NOT NULL COMMENT '사용자 ID (auth_users.id FK)',
  `service_key` varchar(50) NOT NULL COMMENT '외부 서비스 키 (synology, hometax, bank_kb 등)',
  `service_name` varchar(100) NOT NULL COMMENT '외부 서비스 표시 이름',
  `external_login_id` varchar(100) DEFAULT NULL COMMENT '외부 서비스 로그인 ID(아이디/이메일)',
  `external_password` text DEFAULT NULL COMMENT '외부 서비스 비밀번호 (암호화 저장)',
  `external_identifier` varchar(255) DEFAULT NULL COMMENT '외부 서비스 고유 식별자 (UID / DN 등)',
  `access_token` text DEFAULT NULL COMMENT 'Access Token (암호화 저장)',
  `refresh_token` text DEFAULT NULL COMMENT 'Refresh Token (암호화 저장)',
  `token_expires_at` datetime DEFAULT NULL COMMENT 'Access Token 만료 시각',
  `is_connected` tinyint(1) NOT NULL DEFAULT 0 COMMENT '외부 서비스 연결 여부',
  `last_connected_at` datetime DEFAULT NULL COMMENT '마지막 연결 성공 시각',
  `last_error_message` varchar(255) DEFAULT NULL COMMENT '마지막 오류 메시지',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '생성일시',
  `created_by` varchar(100) DEFAULT NULL COMMENT '생성자 ID',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일시',
  `updated_by` varchar(100) DEFAULT NULL COMMENT '수정자 ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_service` (`user_id`,`service_key`) USING BTREE COMMENT '사용자 + 서비스 중복 방지',
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_service_key` (`service_key`) USING BTREE,
  CONSTRAINT `fk_external_accounts_user` FOREIGN KEY (`user_id`) REFERENCES `auth_users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='사용자 외부 서비스 계정 연동 테이블 (Synology, 홈택스, 은행 등)';

