INSERT INTO `dashboard_calendar_events` (`id`,`calendar_id`,`owner_user_id`,`synology_login_id`,`href`,`etag`,`type`,`sequence`,`dtstamp`,`created`,`last_modified`,`title`,`description`,`location`,`event_color`,`admin_event_color`,`dtstart`,`dtend`,`dtstart_ymd`,`dtend_ymd`,`all_day`,`status`,`priority`,`transp`,`alarms_json`,`attendees_json`,`recurrence_json`,`categories_json`,`comments_json`,`attachments_json`,`raw_json`,`is_active`,`synology_exists`,`restored_at`,`deleted_at`,`deleted_by`,`created_at`,`created_by`,`updated_at`,`updated_by`) VALUES ('20250806T232701-ssgkgjgs@cal.synology.com','b157e96b226e113b9da4c478236e2d83','f113b666-ff40-4f93-a7e7-8cea4cdc9c28','이정호','/caldav.php/%EC%9D%B4%EC%A0%95%ED%98%B8/qikaubae/20250806T232701-ssgkgjgs%40cal.synology.com.ics','\"nlbbfmhzikogoeycnjtqwmuxqtxxsdfq\"','VEVENT','2','20250806T233042Z','20250806T232701Z','20250806T233042Z','청주현장_현장미팅','박동환부사장,유병욱부장,강용기팀장 입회\n내용\n1. 비계관련(건축과 간섭되는 부분 고려하여 작업을 해달라요청들어옴)-작업전 사전에 협의후 진행\n2. 보양관련(박동환부사장 지시 후공정이 보양하고 작업해 달라)\nㄴ유병욱부장과 미팅전 대화에서 실랑이 \"석향\"은 보양비가 없다 그러므로 보양을 할수없다고 함.\nㄴ박동환부사장 \"작은것에 큰걸 잃지 마라라\"함.\nㄴ결론 : 보양 스티로폼 50mm 구매후 유리 보양 진행하라 강용기팀장에게 지시함(철물관련은 거래명세서 및 세금계산서 발행후 결제하라함)',NULL,NULL,NULL,'20250806','20250806','20250806','20250806','1',NULL,NULL,'TRANSPARENT',NULL,NULL,NULL,NULL,NULL,NULL,'{\"type\":\"VEVENT\",\"uid\":\"20250806T232701-ssgkgjgs@cal.synology.com\",\"sequence\":\"2\",\"dtstamp\":\"20250806T233042Z\",\"created\":\"20250806T232701Z\",\"last_modified\":\"20250806T233042Z\",\"creator\":null,\"x_syno_creator\":null,\"x_syno_modifier\":null,\"dtstart\":\"20250806\",\"dtend\":\"20250807\",\"due\":null,\"start\":\"2025-08-06\",\"end\":\"2025-08-07\",\"due_iso\":null,\"summary\":\"청주현장_현장미팅\",\"title\":\"청주현장_현장미팅\",\"description\":\"박동환부사장,유병욱부장,강용기팀장 입회\\n내용\\n1. 비계관련(건축과 간섭되는 부분 고려하여 작업을 해달라요청들어옴)-작업전 사전에 협의후 진행\\n2. 보양관련(박동환부사장 지시 후공정이 보양하고 작업해 달라)\\nㄴ유병욱부장과 미팅전 대화에서 실랑이 \\\"석향\\\"은 보양비가 없다 그러므로 보양을 할수없다고 함.\\nㄴ박동환부사장 \\\"작은것에 큰걸 잃지 마라라\\\"함.\\nㄴ결론 : 보양 스티로폼 50mm 구매후 유리 보양 진행하라 강용기팀장에게 지시함(철물관련은 거래명세서 및 세금계산서 발행후 결제하라함)\",\"location\":null,\"categories\":[],\"status\":null,\"priority\":null,\"class\":null,\"transp\":\"TRANSPARENT\",\"url\":null,\"comment\":[],\"contact\":null,\"rrule\":null,\"rdate\":[],\"exdate\":[],\"recurrence_id\":null,\"exrule\":null,\"related_to\":[],\"organizer\":null,\"attendees\":[],\"alarms\":[],\"raw\":{\"DTSTAMP\":{\"value\":\"20250806T233042Z\",\"params\":[]},\"UID\":{\"value\":\"20250806T232701-ssgkgjgs@cal.synology.com\",\"params\":[]},\"SUMMARY\":{\"value\":\"청주현장_현장미팅\",\"params\":[]},\"SEQUENCE\":{\"value\":\"2\",\"params\":[]},\"DTSTART\":{\"value\":\"20250806\",\"params\":{\"VALUE\":\"DATE\"}},\"DTEND\":{\"value\":\"20250807\",\"params\":{\"VALUE\":\"DATE\"}},\"TRANSP\":{\"value\":\"TRANSPARENT\",\"params\":[]},\"CREATED\":{\"value\":\"20250806T232701Z\",\"params\":[]},\"LAST-MODIFIED\":{\"value\":\"20250806T233042Z\",\"params\":[]},\"DESCRIPTION\":{\"value\":\"박동환부사장,유병욱부장,강용기팀장 입회\\n내용\\n1. 비계관련(건축과 간섭되는 부분 고려하여 작업을 해달라요청들어옴)-작업전 사전에 협의후 진행\\n2. 보양관련(박동환부사장 지시 후공정이 보양하고 작업해 달라)\\nㄴ유병욱부장과 미팅전 대화에서 실랑이 \\\"석향\\\"은 보양비가 없다 그러므로 보양을 할수없다고 함.\\nㄴ박동환부사장 \\\"작은것에 큰걸 잃지 마라라\\\"함.\\nㄴ결론 : 보양 스티로폼 50mm 구매후 유리 보양 진행하라 강용기팀장에게 지시함(철물관련은 거래명세서 및 세금계산서 발행후 결제하라함)\",\"params\":[]}},\"_href\":\"\\/caldav.php\\/%EC%9D%B4%EC%A0%95%ED%98%B8\\/qikaubae\\/20250806T232701-ssgkgjgs%40cal.synology.com.ics\",\"_etag\":\"\\\"nlbbfmhzikogoeycnjtqwmuxqtxxsdfq\\\"\",\"calendar_id\":\"b157e96b226e113b9da4c478236e2d83\",\"__meta\":{\"calendar_id\":\"b157e96b226e113b9da4c478236e2d83\",\"collection_href\":\"\\/caldav.php\\/%EC%9D%B4%EC%A0%95%ED%98%B8\\/qikaubae\\/\"},\"extendedProps\":{\"calendar_id\":\"b157e96b226e113b9da4c478236e2d83\",\"collection_href\":\"\\/caldav.php\\/%EC%9D%B4%EC%A0%95%ED%98%B8\\/qikaubae\\/\"}}','1','1',NULL,NULL,NULL,'2026-03-03 10:53:37',NULL,'2026-03-06 15:27:36',NULL);
