INSERT INTO `dashboard_calendar_events` (`id`,`calendar_id`,`owner_user_id`,`synology_login_id`,`href`,`etag`,`type`,`sequence`,`dtstamp`,`created`,`last_modified`,`title`,`description`,`location`,`event_color`,`admin_event_color`,`dtstart`,`dtend`,`dtstart_ymd`,`dtend_ymd`,`all_day`,`status`,`priority`,`transp`,`alarms_json`,`attendees_json`,`recurrence_json`,`categories_json`,`comments_json`,`attachments_json`,`raw_json`,`is_active`,`synology_exists`,`restored_at`,`deleted_at`,`deleted_by`,`created_at`,`created_by`,`updated_at`,`updated_by`) VALUES ('20250926T101656-tjghrwrj@cal.synology.com','b157e96b226e113b9da4c478236e2d83','f113b666-ff40-4f93-a7e7-8cea4cdc9c28','이정호','/caldav.php/%EC%9D%B4%EC%A0%95%ED%98%B8/qikaubae/20250926T101656-tjghrwrj%40cal.synology.com.ics','\"rdppnmznuqciwmmctzpiqcofurbrgtfm\"','VEVENT','3','20250926T101745Z','20250926T101656Z','20250926T101745Z','청주세레니티(회장님현장패트롤)','김주영회장 및 관계자 현장 패트롤\n회장님건의(보양,수도,전기,장비,내진구조서류)>>석재 왠만하면 잘 아껴서 모두 소진해라~\n또한 밝은 회색문양은 가급적 빼달라, 세로작업부위는 수정해라, 청소잘해라~\n또한 돈걱정은 하지마라~ 기성은 다시 올려라, 장비대는 지원해 주겠다함.(1~2만원 수준)\n감리단 미팅: 내진구조검토 확인 및 승인서류를 첨부해야 작업이 가능하다, 이대로는 작업 못한다.\n회장님 전화통화(강용기) 공사는 진행해라. 구조에 대한 서류는 윗선에서 해결하라함.',NULL,NULL,NULL,'20250925','20250925','20250925','20250925','1',NULL,NULL,'TRANSPARENT',NULL,NULL,NULL,NULL,NULL,NULL,'{\"type\":\"VEVENT\",\"uid\":\"20250926T101656-tjghrwrj@cal.synology.com\",\"sequence\":\"3\",\"dtstamp\":\"20250926T101745Z\",\"created\":\"20250926T101656Z\",\"last_modified\":\"20250926T101745Z\",\"creator\":null,\"x_syno_creator\":null,\"x_syno_modifier\":null,\"dtstart\":\"20250925\",\"dtend\":\"20250926\",\"due\":null,\"start\":\"2025-09-25\",\"end\":\"2025-09-26\",\"due_iso\":null,\"summary\":\"청주세레니티(회장님현장패트롤)\",\"title\":\"청주세레니티(회장님현장패트롤)\",\"description\":\"김주영회장 및 관계자 현장 패트롤\\n회장님건의(보양,수도,전기,장비,내진구조서류)>>석재 왠만하면 잘 아껴서 모두 소진해라~\\n또한 밝은 회색문양은 가급적 빼달라, 세로작업부위는 수정해라, 청소잘해라~\\n또한 돈걱정은 하지마라~ 기성은 다시 올려라, 장비대는 지원해 주겠다함.(1~2만원 수준)\\n감리단 미팅: 내진구조검토 확인 및 승인서류를 첨부해야 작업이 가능하다, 이대로는 작업 못한다.\\n회장님 전화통화(강용기) 공사는 진행해라. 구조에 대한 서류는 윗선에서 해결하라함.\",\"location\":null,\"categories\":[],\"status\":null,\"priority\":null,\"class\":null,\"transp\":\"TRANSPARENT\",\"url\":null,\"comment\":[],\"contact\":null,\"rrule\":null,\"rdate\":[],\"exdate\":[],\"recurrence_id\":null,\"exrule\":null,\"related_to\":[],\"organizer\":null,\"attendees\":[],\"alarms\":[],\"raw\":{\"DTSTAMP\":{\"value\":\"20250926T101745Z\",\"params\":[]},\"UID\":{\"value\":\"20250926T101656-tjghrwrj@cal.synology.com\",\"params\":[]},\"SUMMARY\":{\"value\":\"청주세레니티(회장님현장패트롤)\",\"params\":[]},\"SEQUENCE\":{\"value\":\"3\",\"params\":[]},\"DTSTART\":{\"value\":\"20250925\",\"params\":{\"VALUE\":\"DATE\"}},\"DTEND\":{\"value\":\"20250926\",\"params\":{\"VALUE\":\"DATE\"}},\"TRANSP\":{\"value\":\"TRANSPARENT\",\"params\":[]},\"DESCRIPTION\":{\"value\":\"김주영회장 및 관계자 현장 패트롤\\n회장님건의(보양,수도,전기,장비,내진구조서류)>>석재 왠만하면 잘 아껴서 모두 소진해라~\\n또한 밝은 회색문양은 가급적 빼달라, 세로작업부위는 수정해라, 청소잘해라~\\n또한 돈걱정은 하지마라~ 기성은 다시 올려라, 장비대는 지원해 주겠다함.(1~2만원 수준)\\n감리단 미팅: 내진구조검토 확인 및 승인서류를 첨부해야 작업이 가능하다, 이대로는 작업 못한다.\\n회장님 전화통화(강용기) 공사는 진행해라. 구조에 대한 서류는 윗선에서 해결하라함.\",\"params\":[]},\"CREATED\":{\"value\":\"20250926T101656Z\",\"params\":[]},\"LAST-MODIFIED\":{\"value\":\"20250926T101745Z\",\"params\":[]}},\"_href\":\"\\/caldav.php\\/%EC%9D%B4%EC%A0%95%ED%98%B8\\/qikaubae\\/20250926T101656-tjghrwrj%40cal.synology.com.ics\",\"_etag\":\"\\\"rdppnmznuqciwmmctzpiqcofurbrgtfm\\\"\",\"calendar_id\":\"b157e96b226e113b9da4c478236e2d83\",\"__meta\":{\"calendar_id\":\"b157e96b226e113b9da4c478236e2d83\",\"collection_href\":\"\\/caldav.php\\/%EC%9D%B4%EC%A0%95%ED%98%B8\\/qikaubae\\/\"},\"extendedProps\":{\"calendar_id\":\"b157e96b226e113b9da4c478236e2d83\",\"collection_href\":\"\\/caldav.php\\/%EC%9D%B4%EC%A0%95%ED%98%B8\\/qikaubae\\/\"}}','1','1',NULL,NULL,NULL,'2026-03-03 10:53:38',NULL,'2026-03-06 15:27:36',NULL);
